const $$ = (s,root=document)=>Array.from(root.querySelectorAll(s));
const state={workflows:[],workflowId:null,workflow:null,view:'overview',agentMessages:[],activeNode:'source',cleanupId:null,cleanup:null,runId:null,config:null,model:null,records:[],messages:[],corrections:[],explorer:{tab:'overview',mode:'table',records:[],messages:[],quality:null,selected:new Set(),filters:{search:'',status:'active',issue:'all',source:'all',sort:'newest',fieldName:'',fieldOp:'contains',fieldValue:'',dateContains:'',groupBy:'none'}},review:{items:[],selectedId:null,selected:new Set(),position:0,offset:0,query:'',source:'all',issue:'all',sort:'newest',mode:'guided',path:'processed',history:[],undoToken:null,summary:null,settings:null,loading:false,awaitingAdvance:false,sources:[],liveMessage:null,liveMessageId:null,liveRecord:null,livePosition:0,commandBusy:false,liveProgress:null,liveProgressTimer:null,liveProgressMessageId:null},webConnectors:[],webAnalysis:null,webInspector:null,activeWebConnectorId:null,webInspectorPoll:null,webInspectorPollBusy:false,webPickTarget:null,webPickSince:0,webPickRevision:0,diagnostics:[],modelHealth:null,modelStatusPromise:null,modelStatusTimer:null};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=o=>JSON.stringify(o,null,2);
function recordDiagnostic(level,message,details={}){
  const item={time:new Date().toISOString(),level:String(level||'info'),message:String(message||'').slice(0,2000),details};
  state.diagnostics=(state.diagnostics||[]).concat(item).slice(-250);
  const badge=$('#diagnosticsCount');if(badge)badge.textContent=String(state.diagnostics.filter(x=>x.level==='error').length);
}
window.addEventListener('error',e=>recordDiagnostic('error',e.message||'Window error',{source:e.filename,line:e.lineno,column:e.colno}));
window.addEventListener('unhandledrejection',e=>recordDiagnostic('error','Unhandled promise rejection',{reason:String(e.reason?.stack||e.reason||'Unknown').slice(0,1800)}));
const originalConsoleError=console.error.bind(console);
console.error=(...args)=>{recordDiagnostic('error','Browser console error',{args:args.map(x=>String(x?.stack||x)).join(' ').slice(0,1800)});originalConsoleError(...args)};
async function api(url,opts={}){
  const started=performance.now();
  try{
    const res=await fetch(url,opts); const ct=res.headers.get('content-type')||'';
    if(!res.ok){let msg=res.statusText;try{const d=ct.includes('json')?await res.json():await res.text();msg=d.detail||d.message||JSON.stringify(d)}catch{}
      recordDiagnostic('error',`API ${res.status} ${opts.method||'GET'} ${url}`,{error:String(msg).slice(0,1600)});throw new Error(msg)}
    if(ct.includes('application/json'))return res.json(); return res;
  }catch(error){if(!String(error.message||'').includes('API '))recordDiagnostic('error',`Request failed ${opts.method||'GET'} ${url}`,{error:String(error.message||error)});throw error}
}
function diagnosticsText(){return (state.diagnostics||[]).map(x=>`[${x.time}] ${x.level.toUpperCase()} ${x.message}\n${JSON.stringify(x.details||{})}`).join('\n\n')||'No client-side errors recorded.'}
function openDiagnostics(){let panel=$('#diagnosticsPanel');if(!panel){panel=document.createElement('section');panel.id='diagnosticsPanel';panel.className='diagnostics-panel';panel.innerHTML=`<div class="diagnostics-head"><div><b>System diagnostics</b><small>Client errors, API failures and collector state · credentials and message bodies are excluded</small></div><button class="btn btn-quiet btn-sm" id="diagnosticsClose">Close</button></div><div class="diagnostics-actions"><button class="btn btn-secondary btn-sm" id="diagnosticsRefresh">Refresh system state</button><button class="btn btn-primary btn-sm" id="diagnosticsCopy">Copy diagnostics</button><button class="btn btn-quiet btn-sm" id="diagnosticsClear">Clear client errors</button></div><pre id="diagnosticsOutput">Loading diagnostics…</pre>`;document.body.append(panel);panel.querySelector('#diagnosticsClose').onclick=()=>panel.remove();panel.querySelector('#diagnosticsCopy').onclick=()=>navigator.clipboard.writeText(panel.querySelector('#diagnosticsOutput').textContent).then(()=>toast('Diagnostics copied')).catch(()=>toast('Clipboard access failed','error'));panel.querySelector('#diagnosticsClear').onclick=()=>{state.diagnostics=[];renderDiagnosticsOutput()};panel.querySelector('#diagnosticsRefresh').onclick=loadSystemDiagnostics;}panel.hidden=false;loadSystemDiagnostics()}
async function renderDiagnosticsOutput(serverData=null){const out=$('#diagnosticsOutput');if(!out)return;out.textContent=`AGENT SHADI DIAGNOSTICS\nURL: ${location.href}\nBrowser: ${navigator.userAgent}\nViewport: ${innerWidth}x${innerHeight}\nWorkflow: ${state.workflowId||'none'}\nView: ${state.view}\n\nCLIENT EVENTS\n${diagnosticsText()}\n\nSERVER STATE\n${serverData?JSON.stringify(serverData,null,2):'Not loaded'}`}
async function loadSystemDiagnostics(){try{const d=await fetch('/api/diagnostics').then(r=>r.ok?r.json():Promise.reject(new Error(`HTTP ${r.status}`)));await renderDiagnosticsOutput(d)}catch(e){recordDiagnostic('error','Could not load server diagnostics',{error:e.message});await renderDiagnosticsOutput()}}

function toast(message,type='success'){const el=document.createElement('div');el.className='toast '+type;el.textContent=message;$('#toastStack').append(el);setTimeout(()=>el.remove(),4200)}
function setView(view){state.view=view;document.body.classList.toggle('dashboard-view-active',view==='overview');if(view!=='review')document.onkeydown=null;$$('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+view));$$('.nav-item[data-view]').forEach(v=>v.classList.toggle('active',v.dataset.view===view));$('#sidebar').classList.remove('open');renderView(view).catch(err=>{const target=$('#view-'+view);if(target)target.innerHTML=`<div class="warning-box"><b>Could not open ${esc(view)}.</b><br>${esc(err.message||err)}</div>`;toast(`Could not open ${view}: ${err.message||err}`,'error')})}
function workflowId(){return state.workflowId}
function empty(title,desc,icon='◇'){return `<div class="empty"><div class="empty-icon">${icon}</div><b>${esc(title)}</b><p>${esc(desc)}</p></div>`}
function statCard(label,value,detail,icon,glow,tint){return `<div class="card stat" style="--glow:${glow};--tint:${tint}"><span class="stat-icon">${icon}</span><div class="label">${label}</div><div class="value">${value}</div><div class="detail">${detail}</div></div>`}
function pageHead(kicker,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="page-actions">${actions}</div></div>`}
function selectedWorkflowName(){return state.workflow?.name||'Choose a workflow'}
async function refreshBootstrap(){const d=await api('/api/bootstrap');state.workflows=d.workflows;state.model=d.model;state.modelHealth=null;renderWorkflowSelect();updateModelStatus();if(!state.workflowId&&state.workflows.length)state.workflowId=state.workflows[0].id; if(state.workflowId)await loadWorkflow();checkModelStatus({force:true});return d}
function renderWorkflowSelect(){const sel=$('#workflowSelect');sel.innerHTML=state.workflows.map(w=>`<option value="${w.id}" ${w.id===state.workflowId?'selected':''}>${esc(w.name)}</option>`).join('')}
async function loadWorkflow(){state.workflow=await api('/api/workflows/'+state.workflowId);state.config=state.workflow.config;$('#topWorkflowName').textContent=selectedWorkflowName();renderWorkflowSelect();updateNavBadges();}
async function refreshWorkflow(){await loadWorkflow();updateNavBadges()}
async function updateNavBadges(){if(!state.workflowId)return;const c=state.workflow.counts||{};$('#queueBadge').textContent=c.queued||0;$('#reviewBadge').textContent=c.review||0;}
function updateModelStatus(){
  const el=$('#modelStatus');if(!el)return;
  const h=state.modelHealth||{status:'checking',message:'Checking the live model endpoint…'};
  el.classList.remove('ok','offline','checking','inactive','warning');
  const labels={online:`Model online · ${modelShortLabel(h.model||state.model?.model||'LLM')}`,offline:'Model offline',model_unavailable:'Model not loaded',not_configured:'Model needs configuration',disabled:'LLM disabled',rules_only:'Rules-only mode',checking:'Checking model…'};
  const cls=h.status==='online'?'ok':h.status==='offline'?'offline':['model_unavailable','not_configured'].includes(h.status)?'warning':['disabled','rules_only'].includes(h.status)?'inactive':'checking';
  el.classList.add(cls);el.innerHTML=`<i></i> ${esc(labels[h.status]||'Model status unavailable')}`;el.title=`${h.message||'Live connection status'} Click to check again.`;
}
function modelShortLabel(modelId){
  const clean=String(modelId||'').replace(/\\/g,'/').replace(/\/+$/,'');
  const leaf=clean.split('/').pop()||clean;
  return leaf.replace(/\.(gguf|ggml|bin|safetensors|pt|pth)$/i,'')||clean;
}
function setModelSelection(modelId){
  const id=String(modelId||'');const input=$('#modelName');const picker=$('#modelPicker');const manual=$('#modelManualWrap');
  if(input)input.value=id;
  if(picker){const option=Array.from(picker.options).find(o=>o.value===id);picker.value=option?id:'__manual_model__';}
  if(manual)manual.style.display=(!picker||picker.value==='__manual_model__')?'block':'none';
  if(state.model)state.model.model=id;
}
function populateModelPicker(models=[],selected=''){
  const picker=$('#modelPicker');const input=$('#modelName');const manual=$('#modelManualWrap');if(!picker||!input||!manual)return;
  const ids=[...new Set((models||[]).map(x=>String(x||'').trim()).filter(Boolean))];
  const selectedId=String(selected||input.value||'').trim();
  const missing=selectedId&&!ids.includes(selectedId);
  const options=[`<option value="">Choose a model detected by your server…</option>`,...ids.map(id=>`<option value="${esc(id)}" title="${esc(id)}">${esc(modelShortLabel(id))}</option>` )];
  if(missing)options.push(`<option value="${esc(selectedId)}" title="${esc(selectedId)}">${esc(modelShortLabel(selectedId))} · saved selection</option>`);
  options.push('<option value="__manual_model__">Enter model ID manually…</option>');
  picker.innerHTML=options.join('');
  if(selectedId){picker.value=missing?selectedId:selectedId;input.value=selectedId;manual.style.display='none';}
  else if(ids.length){picker.value='';input.value='';manual.style.display='none';}
  else{picker.value='__manual_model__';manual.style.display='block';}
}
async function checkModelStatus({force=false}={}){
  if(state.modelStatusPromise)return state.modelStatusPromise;
  if(force||!state.modelHealth){state.modelHealth={status:'checking',message:'Checking the live model endpoint…'};updateModelStatus();renderModelConnectionSummary();}
  const work=(async()=>{
    try{
      const h=await api(`/api/settings/model/status${force?'?force=true':''}`);
      state.modelHealth=h;
      if(state.model){state.model.connection_verified=!!h.ok;state.model.connection_status=h.ok?'verified':h.status;state.model.available_models=h.models||state.model.available_models||[];}
      const selected=$('#modelName')?.value||state.model?.model||'';
      if($('#modelPicker')&&document.activeElement!==$('#modelName'))populateModelPicker(h.models||state.model?.available_models||[],selected);
      updateModelStatus();renderModelConnectionSummary();return h;
    }catch(e){
      state.modelHealth={status:'offline',ok:false,message:`Could not check model status: ${e.message}`};
      if(state.model)state.model.connection_verified=false;
      updateModelStatus();renderModelConnectionSummary();return state.modelHealth;
    }
  })();
  state.modelStatusPromise=work;
  try{return await work}finally{state.modelStatusPromise=null;}
}
function renderModelConnectionSummary(){
  const host=$('#modelConnectionSummary');if(!host)return;
  const h=state.modelHealth||{status:'checking',message:'Checking the live model endpoint…'};
  const map={online:['green','Online — selected model is available'],offline:['red','Offline — endpoint did not respond'],model_unavailable:['amber','Endpoint online — selected model not loaded'],not_configured:['amber','Configuration required'],disabled:['muted','LLM disabled'],rules_only:['muted','Rules-only mode'],checking:['amber','Checking live connection…']};
  const [kind,label]=map[h.status]||['amber','Status unavailable'];
  const models=(h.models||[]).slice(0,12);
  host.innerHTML=`<div class="model-live-row"><b>Live connection status</b><span class="tag ${kind}">${esc(label)}</span></div><p>${esc(h.message||'')}</p>${models.length?`<div class="model-detected-list"><small class="help">Detected models · choose one from the selector above:</small>${models.map(name=>`<button type="button" class="model-detected-item ${name===($('#modelName')?.value||'')?'selected':''}" data-use-model="${esc(name)}" title="${esc(name)}">${esc(modelShortLabel(name))} <span>Use model</span></button>`).join('')}</div>`:''}<small class="help">Last checked: ${esc(h.checked_at?new Date(h.checked_at).toLocaleTimeString():'Not checked yet')}. Agent Shadi rechecks on startup, every 30 seconds, after settings changes, and when you return to the app.</small>`;
  host.querySelectorAll('[data-use-model]').forEach(button=>button.addEventListener('click',()=>{setModelSelection(button.dataset.useModel);state.modelHealth={status:'checking',message:'Selected model updated locally. Save settings to verify it.'};updateModelStatus();renderModelConnectionSummary();}));
}
function startModelStatusMonitor(){
  if(state.modelStatusTimer)clearInterval(state.modelStatusTimer);
  state.modelStatusTimer=setInterval(()=>{if(!document.hidden)checkModelStatus({force:true})},30000);
  window.addEventListener('focus',()=>checkModelStatus({force:true}));
  window.addEventListener('pageshow',()=>checkModelStatus({force:true}));
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkModelStatus({force:true})});
  const pill=$('#modelStatus');pill?.addEventListener('click',()=>checkModelStatus({force:true}));
  pill?.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();checkModelStatus({force:true})}});
}
async function renderView(view){if(!state.workflowId&&view!=='settings'){await refreshBootstrap()} switch(view){case'overview':return renderOverview();case'builder':return renderBuilder();case'sources':return renderSources();case'inbox':return renderInbox();case'review':return renderReview();case'cleanup':return renderCleanup();case'export':return renderExport();case'learning':return renderLearning();case'settings':return renderSettings();case'agent':return renderAgent();}}

