  const fileInput=$('#fileUpload'),dropzone=$('#dropzone');$('#chooseFile').onclick=e=>{e.stopPropagation();fileInput.click()};dropzone.addEventListener('click',e=>{if(e.target!==$('#chooseFile'))fileInput.click()});dropzone.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fileInput.click()}});fileInput.onchange=e=>{uploadFile(e.target.files[0]);e.target.value=''};
