  $('#wcPersistSession').checked=c.session?.persist!==false;$('#wcNavStrategy').value=n.strategy||'manual';$('#wcDateRangeMode').value=n.date_range_mode||'auto';$('#wcScrollSelector').value=n.scroll_selector||'';$('#wcButtonSelector').value=n.button_selector||'';$('#wcPreviousPage').value=n.previous_page_selector||'';$('#wcNextPage').value=n.next_page_selector||'';$('#wcDirection').value=n.direction||'up';$('#wcWaitMode').value=n.wait_mode||'adaptive';$('#wcWait').value=n.wait_ms||1200;$('#wcMinWait').value=n.min_wait_ms||250;$('#wcMaxWait').value=n.max_wait_ms||8000;$('#wcStableWait').value=n.stable_ms||350;$('#wcScrollStep').value=n.scroll_step_ratio||0.78;$('#wcScrollPx').value=n.scroll_amount_px||0;$('#wcMaxIdle').value=n.max_idle_cycles||6;$('#wcTimezone').value=n.timestamp_timezone||(c.site_preset==='eitaa'?'Asia/Tehran':'UTC');$('#wcMaxScrolls').value=n.max_scrolls||30;
