async function refreshWebCollectionBrowserStatus(connectorId=$('#collectWebConnector')?.value){
  const host=$('#collectWebBrowserStatus');
  if(!host||!connectorId){if(host)host.textContent='Choose a saved connector, then open its browser session.';return null;}
  try{
    const d=await api(`/api/web-connectors/${connectorId}/inspect/status`);
    const session=d.session||{};
    const profileNote=session.persistent
      ? (session.has_saved_site_data?'Saved browser profile contains browser site-storage data (cookies, local storage, IndexedDB or session storage). The website may still expire or revoke a login.':'Persistent browser profile exists, but no site-storage database has been detected yet. Sign in once and close the browser normally to retain site data.')
      : 'Temporary profile: sign-in data is removed when the browser closes.';
    host.innerHTML=d.status==='ready'?`<span class="tag green">Browser ready</span> Browser is open. ${esc(profileNote)} Shadi checks the configured target URL, username and platform ID against the active conversation before collecting.`:d.status==='failed'?`<span class="tag red">Browser failed</span> ${esc(d.error||'Open the browser again.')}`:`<span class="tag amber">Browser ${esc(d.status||'idle')}</span> ${esc(profileNote)} Open the saved browser session before collecting.`;
    if(session.profile_directory)host.innerHTML+=`<small class="help">Profile: <code>${esc(session.profile_directory)}</code> · ${Number(session.profile_bytes||0).toLocaleString()} bytes tracked</small>`;
    if(['ready','failed','browser_closed','stopped'].includes(d.status)&&state.webCollectionPoll){clearInterval(state.webCollectionPoll);state.webCollectionPoll=null;}
    return d;
  }catch(e){host.textContent='Open the saved browser session before collecting.';return null;}
}
async function openSelectedWebCollectionBrowser(){
  const connectorId=$('#collectWebConnector')?.value;
  if(!connectorId)throw new Error('Choose a saved web connector first.');
  const current=await api(`/api/web-connectors/${connectorId}/inspect/status`);
  if(current.status==='ready'){await refreshWebCollectionBrowserStatus(connectorId);toast('Saved connector browser is already open');return current;}
  const started=await api(`/api/web-connectors/${connectorId}/inspect/start`,{method:'POST'});
  const host=$('#collectWebBrowserStatus');
  if(host)host.innerHTML=`<span class="tag amber">Browser ${esc(started.status||'starting')}</span> Chromium is opening the saved application. Sign in and open the intended conversation; collection checks its active header and stable identity before reading messages.`;
  if(state.webCollectionPoll)clearInterval(state.webCollectionPoll);
  state.webCollectionPoll=setInterval(()=>refreshWebCollectionBrowserStatus(connectorId),1500);
  await refreshWebCollectionBrowserStatus(connectorId);
  toast('Saved web connector browser opened');
  return started;
}
