    box.innerHTML=`<div class="web-inspector-state"><div><span class="tag ${d.status==='ready'?'green':d.status==='failed'?'red':'amber'}">Browser: ${esc(d.status)}</span><p class="muted">${d.status==='ready'?'Browser connected. In Step 3, choose a Pick button and click the matching element. For message text, avoid emojis and links; for timestamps, click the time element.':d.status==='failed'?esc(d.error||'Browser launch failed'):'Browser session status is being checked.'}</p><small class="help">${esc(sessionNote)}</small>${uidNote?`<small class="help">${esc(uidNote)}</small>`:''}${session.profile_directory?`<small class="help">Profile: <code>${esc(session.profile_directory)}</code></small>`:''}</div>${selected?`<div class="web-selected-element"><b>Last selected element</b><code>${esc(selected.selector)}</code><small>Reusable message root: <code>${esc(selected.root_selector||'not detected')}</code> · ${Number(selected.repeated_count||0)} matches</small><small>Field within message: <code>${esc(selected.field_selector||selected.relative_selector||selected.selector)}</code></small><small>${esc(selected.tag)} · ${esc((selected.text||'').slice(0,160))}</small><div class="page-actions">${[['root','Use as message root'],['text','Use as text'],['sender','Use as sender'],['timestamp','Use as timestamp'],['message_id','Use as message ID'],['attachment','Use as attachment']].map(([k,label])=>`<button class="btn btn-quiet btn-sm" data-wc-apply="${k}">${label}</button>`).join('')}<button class="btn btn-secondary btn-sm" data-wc-html="individual">Use exact HTML as one message</button><button class="btn btn-secondary btn-sm" data-wc-html="list">Use exact HTML as message list</button></div></div>`:''}${d.error?`<div class="warning-box">${esc(d.error)}</div>`:''}</div>`;
    $('#startWebInspector').disabled=d.status==='ready'||!state.activeWebConnectorId;$('#stopWebInspector').disabled=!['ready','starting'].includes(d.status);$('#captureWebVisible').disabled=d.status!=='ready';$('#collectWebHistory').disabled=d.status!=='ready';if($('#wcAgentObserve'))$('#wcAgentObserve').disabled=d.status!=='ready';if($('#wcAgentStep'))$('#wcAgentStep').disabled=d.status!=='ready';
