  $('#collectionPolicyRules').onclick=e=>{const b=e.target.closest('[data-remove-rule]');if(!b)return;state.collectionPolicyDraft.rules.splice(Number(b.dataset.removeRule),1);renderCollectionPolicyEditor()};
