function parseChannelLines(text){return text.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map((line,i)=>{const p=line.split('|').map(x=>x.trim());if(!p[0])throw new Error(`Line ${i+1}: missing username`);return {username:p[0].replace(/^@/,''),url:p[1]||'',search_name:p[2]||p[0],deal_type:p[3]||'sale'}})}
async function saveChannels(){try{const telegram_channels=parseChannelLines($('#telegramChannels').value),rubika_channels=parseChannelLines($('#rubikaChannels').value);await api(`/api/workflows/${workflowId()}/collector`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({telegram_channels,rubika_channels,filter_mode:['all','real_estate'].includes(state.collectionPolicyDraft.mode)?state.collectionPolicyDraft.mode:'all',collection_policy:{version:1,mode:state.collectionPolicyDraft.mode,logic:state.collectionPolicyDraft.logic||'all',rules:state.collectionPolicyDraft.rules||[]},date_system:$('#collectDateSystem').value,custom_date_format:$('#collectDateFormat')?.value||'',auto_process:$('#autoProcess').checked})});toast('Channel configuration saved locally');return true}catch(e){toast(e.message,'error');throw e}}
async function runCollector(){
  try{
    if($('#collectPlatform').value==='web'){
      // Persist the same workflow-wide collection policy and date-system choice
      // used by the Telegram/Rubika collection settings before importing web posts.
      await saveChannels();
      const connectorId=$('#collectWebConnector').value;
      if(!connectorId)throw new Error('Choose a saved connector first.');
      if(!$('#collectStart').value.trim()||!$('#collectEnd').value.trim())throw new Error('Enter both Start date and End date.');
      const browser=await api(`/api/web-connectors/${connectorId}/inspect/status`);
      if(browser.status!=='ready'){
        await refreshWebCollectionBrowserStatus(connectorId);
        throw new Error('The saved browser session is not ready. Press “1 · Open source browser” and complete sign-in if needed. Then manually open the one channel/page you want before starting collection.');
      }
      state.activeWebConnectorId=connectorId;
      const saved=wcGetSaved(connectorId), identity=saved?.config?.channel||{};const channelName=$('#collectWebChannelName')?.value.trim()||identity.name||'';
      await webCapture('collect',{connectorId,channelName,maxMessages:Number($('#collectWebMaxMessages').value||1000),autoProcess:$('#autoProcess').checked});
      return;
    }
    await saveChannels();
    const d=await api(`/api/workflows/${workflowId()}/collect/run`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({platform:$('#collectPlatform').value,start_date:$('#collectStart').value.trim(),end_date:$('#collectEnd').value.trim(),date_system:$('#collectDateSystem').value,custom_date_format:$('#collectDateFormat')?.value||'',auto_process:$('#autoProcess').checked,filter_mode:['all','real_estate'].includes(state.collectionPolicyDraft.mode)?state.collectionPolicyDraft.mode:'all'})});
    toast(`Collection started · ${d.input_start_date} to ${d.input_end_date}`);await pollCollector();
  }catch(e){toast(e.message,'error');const host=$('#collectorStatus');if(host)host.innerHTML=`<div class="warning-box">${esc(e.message)}</div>`;}
}
function collectorSourceBreakdown(manifest){
  if(!manifest||typeof manifest!=='object')return '';
  const counts={};
  if(manifest.run_scope_source_counts&&typeof manifest.run_scope_source_counts==='object'){
    Object.assign(counts,manifest.run_scope_source_counts);
  }else{
    for(const day of (manifest.days||[]))for(const output of Object.values(day.outputs||{}))for(const [source,stats] of Object.entries(output.sources||{})){
      counts[source]=(counts[source]||0)+Number(stats.unique_added??stats.read??0);
    }
  }
  const items=Object.entries(counts).map(([source,count])=>`${source.replace(':',' · ')}: ${count}`);
  for(const failure of (manifest.collector_warnings||[])){
    const key=`${failure.platform||'source'}:${failure.username||failure.channel||'channel'}`;
    if(!counts[key])items.push(`${key.replace(':',' · ')}: failed`);
  }
  return items.join(' · ');
}
async function pollCollector(){
  const box=$('#collectorStatus');
  if(!box||!state.workflowId)return;
  try{
    const d=await api(`/api/workflows/${workflowId()}/collect/status`);
    if(!d||d.status==='idle')return;
    const operatorPaused=d.status==='operator_paused';
    const operatorSelecting=d.status==='running'&&d.phase==='operator_select_channel';
    const resumeRequested=d.status==='resume_requested';
    const legacyInspectorPaused=d.status==='inspector_paused';
    const active=['queued','running','resume_requested'].includes(d.status);
    const partialErrors=d.status==='completed_with_errors';
    const manualHistoryRecovery=operatorPaused&&/MANUAL HISTORY RECOVERY/i.test(String(d.phase_message||''));
    const statusLabel=operatorSelecting?'Select channel in browser':manualHistoryRecovery?'Manual history recovery':operatorPaused?'Confirm selected channel':legacyInspectorPaused?'Legacy Playwright Inspector pause':resumeRequested?'Continuing…':partialErrors?'Completed with collection errors':d.status;
    const operatorPlatform=String(d.platform||'').toLowerCase()==='telegram'?'Telegram':String(d.platform||'').toLowerCase()==='rubika'?'Rubika':esc(d.platform||'source');
    const operatorSelectHint=operatorSelecting?`<div class="hint-box" style="margin:12px 0"><b>Choose the intended ${operatorPlatform} channel in the browser.</b><p style="margin:6px 0 0">The collector found search results but could not safely open one automatically. Click the correct channel row in the open browser (not just a message preview). Keep the browser open. Agent Shadi will detect the active chat and then show the normal <b>Continue collection</b> button.</p><small style="display:block;margin-top:8px">Do not close the browser or use Playwright Inspector controls. Do not press Enter again after the result appears; click the correct channel row once.</small></div>`:'';
    const manualIdentityMismatch=operatorPaused&&!manualHistoryRecovery&&/MISMATCH|NOT PROVEN/i.test(String(d.phase_message||''));
    const operatorHint=operatorPaused?`<div class="hint-box" style="margin:12px 0;border:1px solid ${manualIdentityMismatch?'var(--danger,#c66)':'var(--border,#888)'}"><b>${manualHistoryRecovery?'Automatic history scrolling needs help.':manualIdentityMismatch?'The selected result and active chat header do not match.':'Confirm the selected channel before scanning.'}</b><p style="margin:6px 0 10px">${manualHistoryRecovery?'Keep the same channel open. Hover the actual message list—not the sidebar or page background—and scroll upward until older messages appear. The collector will verify the channel and visible history again after you continue.':`${operatorPlatform} may display a channel title instead of its saved @username. Compare the clicked result and active chat header with the channel you intended. ${manualIdentityMismatch?'<b>Do not continue unless you independently recognize this as the correct channel.</b>':'The displayed title is not independently verified as proof of username ownership; confirm the channel yourself.'} Position history near the requested <b>end date</b> after confirming the channel.`}</p><button class="btn btn-primary" id="continueCollection">${manualHistoryRecovery?'✓ Continue history':manualIdentityMismatch?'⚠ Continue only — I verified this channel':'✓ Confirm channel & continue'}</button><small style="display:block;margin-top:8px">Channel: ${esc(d.waiting_for||d.channel||'configured channel')} · No Playwright Inspector controls are needed.</small></div>`:'';
    const legacyInspectorHint=legacyInspectorPaused?`<div class="hint-box" style="margin:12px 0"><b>This is an older debugger-based collection run.</b><p style="margin:6px 0 0">For this existing run only, use Resume once in Playwright Inspector. New runs use the Continue collection button inside Agent Shadi.</p></div>`:'';
    const phaseLine=d.phase_message?`<div class="collection-activity-label"><b>${esc((d.platform||'Collector').toUpperCase())}${d.channel?' · '+esc(d.channel):''}</b><br>${esc(d.phase_message)}</div>`:'';
    const activity=active?`<div class="collection-activity" role="status" aria-live="polite"><div class="collection-progress"><span></span></div>${phaseLine||'<div class="collection-activity-label">Collection is running. Waiting for the next verified browser phase…</div>'}</div>`:phaseLine?`<div class="hint-box" style="margin:10px 0">${phaseLine}</div>`:'';
    const logLines=(d.logs||[]).slice(-80);
    const pageY=window.scrollY;
    const sourceBreakdown=d.result?.manifest?collectorSourceBreakdown(d.result.manifest):'';
    box.innerHTML=`<div class="card" style="padding:13px"><div class="card-head"><b>Collection status</b><span class="tag ${d.status==='completed'?'green':d.status==='failed'?'red':operatorSelecting||operatorPaused||legacyInspectorPaused?'violet':'amber'}">${esc(statusLabel)}</span></div>${operatorSelectHint}${operatorHint}${legacyInspectorHint}${activity}${d.result?`<div class="success-box">${d.result.manifest?.run_scope_captured_count??d.result.imported} messages found in selected platform(s) · ${d.result.imported} new inbox items · ${d.result.queued??d.result.imported} queued · ${d.result.filtered||0} held · ${d.result.duplicates} duplicates · ${d.result.suppressed||0} previously deleted and suppressed</div>${sourceBreakdown?`<div class="hint-box"><b>Selected-platform sources:</b> ${esc(sourceBreakdown)}. Previously archived messages from platforms not selected in this run are not imported.</div>`:''}`:''}${d.error?`<div class="warning-box">${esc(d.error)}</div>`:''}<div class="log-box" id="collectorLog" aria-label="Live collection output" aria-live="polite">${logLines.map(x=>`<div class="log-line">${esc(x)}</div>`).join('')}</div></div>`;
    // The log panel is re-rendered on each status poll. Always pin it to its
    // newest line so users never have to scroll down manually during a run.
    const log=$('#collectorLog');
    if(log)log.scrollTop=log.scrollHeight;
    const continueButton=$('#continueCollection');
    if(continueButton)continueButton.onclick=async()=>{
      continueButton.disabled=true;
      continueButton.textContent='Continuing…';
      try{
        await api(`/api/workflows/${workflowId()}/collect/resume`,{method:'POST'});
        toast('Continue received · verifying channel and message history');
        await pollCollector();
      }catch(e){
        toast(e.message,'error');
        continueButton.disabled=false;
        continueButton.textContent=manualHistoryRecovery?'✓ Continue history':manualIdentityMismatch?'⚠ Continue only — I verified this channel':'✓ Confirm channel & continue';
      }
    };
    // Preserve the outer page position as the live status card grows.
    if(Math.abs(window.scrollY-pageY)>2)window.scrollTo(0,pageY);
  }catch{}
}
