async function loadMoreExplorerRecords(){
  const x=state.explorer;if(!x)return;
  try{const batch=await api(`/api/workflows/${workflowId()}/records?status=all&limit=1000&offset=${x.recordsLoaded||0}`);if(!batch.length){toast('No more records to load.');return}const seen=new Set(x.records.map(r=>r.id)),qMap=x.quality?.record_quality||{};for(const r of batch)if(qMap[r.id])r.quality=qMap[r.id];x.records.push(...batch.filter(r=>!seen.has(r.id)));x.recordsLoaded=x.records.length;toast(`Loaded ${batch.length} more records`);renderExplorerTab()}catch(e){toast(e.message,'error')}
}
async function loadMoreExplorerMessages(){
  const x=state.explorer;if(!x)return;
  try{const batch=await api(`/api/workflows/${workflowId()}/messages?limit=1000&offset=${x.messagesLoaded||0}`);if(!batch.length){toast('No more messages to load.');return}const seen=new Set(x.messages.map(m=>m.id));x.messages.push(...batch.filter(m=>!seen.has(m.id)));x.messagesLoaded=x.messages.length;toast(`Loaded ${batch.length} more source messages`);renderExplorerTab()}catch(e){toast(e.message,'error')}
}

function formatExplorerValue(v){if(v===null||v===undefined||v==='')return '<span class="missing-value">—</span>';if(typeof v==='object')return esc(JSON.stringify(v));return esc(String(v))}
function qualityFlagsHtml(q){if(!q?.flags?.length)return '<span class="tag green">No flags</span>';return `<div class="flag-stack">${q.flags.slice(0,3).map(f=>`<span class="quality-flag ${esc(f.severity)}" title="${esc(f.detail)}">${esc(f.label)}</span>`).join('')}${q.flags.length>3?`<span class="tag">+${q.flags.length-3}</span>`:''}</div>`}
function recordHeadline(r){const vals=Object.entries(r.data||{}).filter(([k,v])=>v!==null&&v!==''&&!(Array.isArray(v)&&v.length===0)&&!(typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).length===0)).slice(0,2).map(([k,v])=>typeof v==='object'?JSON.stringify(v):String(v));return vals.join(' · ')||'No useful fields extracted'}
function filteredExplorerRecords(){
  const f=state.explorer.filters;let rows=[...state.explorer.records];
  if(f.status==='active')rows=rows.filter(r=>!['deleted','duplicate_removed'].includes(r.status));
  else if(f.status!=='all')rows=rows.filter(r=>r.status===f.status);
  if(f.source!=='all')rows=rows.filter(r=>r.source===f.source);
  if(f.issue==='flagged')rows=rows.filter(r=>r.quality?.is_flagged);
  else if(f.issue==='clean')rows=rows.filter(r=>!r.quality?.is_flagged);
  else if(f.issue!=='all')rows=rows.filter(r=>(r.quality?.flags||[]).some(x=>x.code===f.issue));
  const q=(f.search||'').trim().toLocaleLowerCase();
  if(q)rows=rows.filter(r=>`${r.raw_text} ${JSON.stringify(r.data)} ${r.source} ${r.status} ${r.posted_at||''} ${(r.warnings||[]).join(' ')} ${(r.errors||[]).join(' ')}`.toLocaleLowerCase().includes(q));
  const dateNeedle=(f.dateContains||'').trim().toLocaleLowerCase();
  if(dateNeedle)rows=rows.filter(r=>String(r.posted_at||'').toLocaleLowerCase().includes(dateNeedle));
  if(f.fieldName){
    const op=f.fieldOp||'contains',needle=(f.fieldValue||'').trim().toLocaleLowerCase();
    rows=rows.filter(r=>{
      const value=r.data?.[f.fieldName],filled=value!==null&&value!==undefined&&value!==''&&!(Array.isArray(value)&&!value.length)&&!(typeof value==='object'&&!Array.isArray(value)&&!Object.keys(value).length);
      if(op==='empty')return !filled;
      if(op==='not_empty')return filled;
      if(!filled)return false;
      if(op==='equals')return String(value).toLocaleLowerCase()===needle;
      if(op==='contains')return String(typeof value==='object'?JSON.stringify(value):value).toLocaleLowerCase().includes(needle);
      if(op==='gt'||op==='lt'){const a=Number(value),b=Number(f.fieldValue);return Number.isFinite(a)&&Number.isFinite(b)&&(op==='gt'?a>b:a<b)}
      return true;
    });
  }
  const dateValue=r=>{const raw=String(r.posted_at||r.created_at||'').trim();const digits=raw.replace(/[۰-۹]/g,ch=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(ch)).replace(/[٠-٩]/g,ch=>'٠١٢٣٤٥٦٧٨٩'.indexOf(ch));const m=digits.match(/^(\d{4})[.\/\-](\d{1,2})[.\/\-](\d{1,2})(.*)$/);if(m)return `${m[1]}${String(m[2]).padStart(2,'0')}${String(m[3]).padStart(2,'0')}${m[4]}`;const parsed=Date.parse(raw);return Number.isFinite(parsed)?String(parsed).padStart(16,'0'):raw};
  if(f.sort==='oldest')rows.sort((a,b)=>dateValue(a).localeCompare(dateValue(b)));
  else if(f.sort==='coverage-low')rows.sort((a,b)=>(a.quality?.completeness||0)-(b.quality?.completeness||0));
  else if(f.sort==='coverage-high')rows.sort((a,b)=>(b.quality?.completeness||0)-(a.quality?.completeness||0));
  else if(f.sort==='flags')rows.sort((a,b)=>(b.quality?.flag_count||0)-(a.quality?.flag_count||0));
  else if(f.sort==='source')rows.sort((a,b)=>String(a.source||'').localeCompare(String(b.source||'')));
  else rows.sort((a,b)=>dateValue(b).localeCompare(dateValue(a)));
  return rows;
}
function explorerGroupKey(r,groupBy){
  if(!groupBy||groupBy==='none')return 'All matching records';
  if(groupBy==='source')return r.source||'(Unknown source)';
  if(groupBy==='status')return r.status||'(No status)';
  if(groupBy==='date')return r.posted_at||'(No date)';
  if(groupBy==='month')return String(r.posted_at||'').slice(0,7)||'(No date)';
  if(groupBy==='quality')return r.quality?.is_flagged?'Needs attention':'No quality flags';
  if(groupBy.startsWith('field:')){const name=groupBy.slice(6),v=r.data?.[name];return v===null||v===undefined||v===''?'(Empty)':String(typeof v==='object'?JSON.stringify(v):v)}
  return 'All matching records';
}
