  const renderCards=(items)=>`<div class="explorer-card-grid">${items.map(r=>`<article class="record-card explorer-record-card"><div class="record-top"><label class="select-record"><input type="checkbox" data-select-record="${r.id}" ${selected.has(r.id)?'checked':''}> Select</label><span class="tag ${r.status==='approved'?'green':r.status==='deleted'?'red':'amber'}">${esc(r.status)}</span></div><div class="record-card-heading"><b>${esc(recordHeadline(r))}</b><small>${esc(r.source)} · ${esc(r.posted_at||'Date unavailable')}</small></div><div class="record-fields">${fields.map(f=>`<div class="record-field"><small>${esc(f.label||f.name)}</small><b>${formatExplorerValue(r.data?.[f.name])}</b><em>${esc(r.provenance?.[f.name]||'Not supplied')}</em></div>`).join('')}</div><div class="record-quality-line"><span>Field coverage</span><b>${r.quality?.completeness??0}%</b>${qualityFlagsHtml(r.quality)}</div><div class="record-actions"><button class="btn btn-secondary btn-sm" data-inspect-record="${r.id}">Inspect</button><button class="btn btn-secondary btn-sm" data-edit-record="${r.id}">Edit fields</button><button class="btn btn-danger btn-sm" data-trash-record="${r.id}" ${r.status==='deleted'?'disabled':''}>Delete</button></div></article>`).join('')}</div>`;
  const body=groupEntries.map(([label,items])=>`<section class="explorer-group"><div class="explorer-group-head"><b>${esc(label)}</b><span>${items.length} records</span></div>${state.explorer.mode==='cards'?renderCards(items):renderTable(items)}</section>`).join('');
  host.innerHTML=toolbar+(rows.length?body:empty('No records match these filters','Change the filters or import more data.'))+((state.explorer.records.length<(state.explorer.quality?.records||0))?`<div class="load-more-row"><span>${state.explorer.records.length.toLocaleString()} of ${(state.explorer.quality.records||0).toLocaleString()} records loaded</span><button class="btn btn-secondary" id="loadMoreRecords">Load next batch of records</button></div>`:'');
  const bulk=$('#explorerBulkBar');if(bulk){bulk.innerHTML=selected.size?`<span><b>${selected.size}</b> selected</span><div>${selected.size>=2&&selected.size<=4?'<button class="btn btn-secondary btn-sm" id="compareSelectedRecords">Compare selected</button>':''}<button class="btn btn-secondary btn-sm" data-bulk-action="approve">Approve selected</button><button class="btn btn-secondary btn-sm" data-bulk-action="reject">Mark unrelated</button><button class="btn btn-danger btn-sm" data-bulk-action="trash">Move to trash</button><button class="btn btn-quiet btn-sm" id="clearRecordSelection">Clear selection</button></div>`:`<span class="muted">Select records to compare, approve, mark unrelated or move to trash.</span>`;}
