  showModal(`<div class="modal-head"><div><div class="eyebrow">SIDE-BY-SIDE DATA REVIEW</div><h2>Compare ${rows.length} selected records</h2><p class="muted">Highlighted rows have different values between the selected records.</p></div><button id="closeCompare">×</button></div><div class="compare-table-wrap"><table class="data-table compare-table"><thead><tr><th>Field</th>${rows.map((r,i)=>`<th>Record ${i+1}<small>${esc(r.source||'Unknown')} · ${esc(r.posted_at||'No date')}</small></th>`).join('')}</tr></thead><tbody>${values}<tr><th>Quality / status</th>${rows.map(r=>`<td>${esc(r.status)} · ${r.quality?.completeness??0}% coverage ${qualityFlagsHtml(r.quality)}</td>`).join('')}</tr></tbody></table></div><div class="modal-actions"><button class="btn btn-secondary" id="closeCompareBottom">Close</button></div>`);
