    bind('explorerSearch','search');bind('explorerStatus','status');bind('explorerIssue','issue');bind('explorerSource','source');bind('explorerSort','sort');bind('explorerDateContains','dateContains');bind('explorerFieldName','fieldName');bind('explorerFieldOp','fieldOp');bind('explorerFieldValue','fieldValue');bind('explorerGroupBy','groupBy');
    $('#recordTableMode').onclick=()=>{state.explorer.mode='table';renderExplorerTab()};$('#recordCardMode').onclick=()=>{state.explorer.mode='cards';renderExplorerTab()};$('#recordCompactMode').onclick=()=>{state.explorer.mode='compact';renderExplorerTab()};
    $$('[data-preset]').forEach(b=>b.onclick=()=>{const preset=b.dataset.preset;const f=state.explorer.filters;if(preset==='all'){f.status='active';f.issue='all'}else if(preset==='approved'){f.status='approved';f.issue='all'}else if(preset==='deleted'){f.status='deleted';f.issue='all'}else{f.status='active';f.issue=preset==='flagged'?'flagged':preset}renderExplorerTab()});
    $('#clearExplorerFilters').onclick=()=>{state.explorer.filters={search:'',status:'active',issue:'all',source:'all',sort:'newest',fieldName:'',fieldOp:'contains',fieldValue:'',dateContains:'',groupBy:'none'};renderExplorerTab()};
