  $$('[data-select-message]').forEach(cb=>cb.onchange=()=>{if(cb.checked){if(selected.size>=500){cb.checked=false;toast('Select up to 500 messages per bulk action.','error');return}selected.add(cb.dataset.selectMessage)}else selected.delete(cb.dataset.selectMessage);renderExplorerMessageRows()});
  const all=$('#selectVisibleMessages');if(all)all.onchange=()=>{let skipped=0;for(const m of rows){if(all.checked&&!selected.has(m.id)){if(selected.size<500)selected.add(m.id);else skipped++}else if(!all.checked)selected.delete(m.id)}if(skipped)toast(`Bulk selection is limited to 500 messages; ${skipped} were not selected.`,'error');renderExplorerMessageRows()};
