async function openClearInbox(){
  try{
    const summary=await api(`/api/workflows/${workflowId()}/messages/summary`);
    if(summary.busy){toast(`${summary.busy_reason} Wait until it finishes before clearing messages.`,'error');return;}
    showModal(`<div class="modal-head"><div><div class="eyebrow">MESSAGE INBOX</div><h2>Clear inbox</h2></div><button id="closeClearInbox" aria-label="Close">×</button></div>
      <p class="muted">Choose what to remove from <b>${esc(selectedWorkflowName())}</b>. This only affects the selected workflow.</p>
      <div class="field"><label for="clearInboxScope">What should be cleared?</label><select id="clearInboxScope" class="input"><option value="pending">All unprocessed messages, including held by policy (${summary.clearable??summary.pending})</option><option value="all">All inbox messages (${summary.messages}) and their extracted results</option></select></div>
      <div id="clearInboxPreview" class="hint-box" style="margin-top:12px"></div>
      <div id="clearInboxAllConfirm" class="warning-box" style="display:none;margin-top:10px"><label class="toggle-row"><input type="checkbox" id="confirmClearAll"> I understand that extracted records and correction history for this workflow will also be deleted.</label></div>
      <div class="modal-actions"><button class="btn btn-quiet" id="cancelClearInbox">Cancel</button><button class="btn btn-danger" id="confirmClearInbox">Clear selected messages</button></div>`);
    const updatePreview=()=>{
      const all=$('#clearInboxScope').value==='all';
      $('#clearInboxPreview').innerHTML=all
        ? `<b>Full workflow inbox reset</b><br>Will remove ${summary.messages} messages, ${summary.records} extracted records and ${summary.corrections} correction entries. Workflow prompt, schema, channel URLs, source archives, exports and browser sessions will be kept. Deleted message fingerprints are suppressed from future collection imports.`
        : `<b>Clear unprocessed messages</b><br>Will remove ${summary.clearable??summary.pending} unprocessed messages, including ${summary.filtered||0} held by collection policy, ${summary.pending} waiting/failed and ${summary.interrupted||0} interrupted messages, plus linked partial results. Successfully processed messages and their extracted records remain. Your separate collector source archives are not deleted, but cleared messages are suppressed from future collection imports.`;
      $('#clearInboxAllConfirm').style.display=all?'block':'none';
      $('#confirmClearInbox').disabled=all&&!$('#confirmClearAll').checked;
      $('#confirmClearInbox').textContent=all?'Clear entire workflow inbox':'Clear unprocessed messages';
    };
    $('#closeClearInbox').onclick=closeModal;$('#cancelClearInbox').onclick=closeModal;
    $('#clearInboxScope').onchange=updatePreview;
    $('#confirmClearAll').onchange=updatePreview;
    updatePreview();
    $('#confirmClearInbox').onclick=async()=>{
      const scope=$('#clearInboxScope').value;
      if(scope==='all'&&!$('#confirmClearAll').checked)return;
      const btn=$('#confirmClearInbox');btn.disabled=true;btn.textContent='Clearing…';
      try{const result=await api(`/api/workflows/${workflowId()}/messages/clear`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scope})});closeModal();toast(`Removed ${result.messages_deleted} messages, ${result.records_deleted} records and ${result.corrections_deleted} corrections`);await refreshWorkflow();await renderInbox();}
      catch(e){btn.disabled=false;btn.textContent='Try again';toast(e.message,'error')}
    };
  }catch(e){toast(e.message,'error')}
}
function renderMessageRows(rows){if(!rows.length)return empty('No source messages yet','Paste some messages or upload a file to begin.','▤');return rows.map(m=>`<div class="message-card"><div class="message-meta"><span>${esc(m.source)}</span><span>${esc(m.posted_at||'Date unavailable')}</span><span class="tag ${m.status==='processed'?'green':m.status==='failed'?'red':'amber'}">${esc(m.status)}</span><span style="margin-left:auto">${esc(m.created_at?.slice(0,16)||'')}</span></div><div class="msg-text">${esc(m.raw_text)}</div>${m.error?`<div class="warning-box" style="margin-top:8px">${esc(m.error)}</div>`:''}</div>`).join('')}
async function startProcessing(){if((state.config?.review_settings||{}).processing_path==='live'){toast('This workflow uses Live AI one by one. Opening Review Studio instead of starting batch extraction.','info');await setView('review');return;}try{const d=await api(`/api/workflows/${workflowId()}/process`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({include_processed:false,limit:10000})});state.runId=d.run_id;toast(`Extraction started for ${d.total} messages`);if(state.view==='overview'||state.view==='inbox')await renderRunProgress()}catch(e){const box=$('#runProgress');if(box)box.innerHTML=`<div class="warning-box"><b>Extraction was not started.</b><br>${esc(e.message)}<br><button class="btn btn-secondary btn-sm" style="margin-top:9px" data-nav="settings">Open Model & Settings</button></div>`;const settingsButton=box?.querySelector('[data-nav="settings"]');if(settingsButton)settingsButton.onclick=()=>setView('settings');toast(e.message,'error')}}
async function renderRunProgress(){const box=$('#runProgress');if(box)box.innerHTML='<div class="card"><b>Connecting to process monitor…</b></div>';if(state.runPoll)clearInterval(state.runPoll);state.runPoll=setInterval(pollRun,1100);pollRun()}
async function controlBackgroundRun(action){if(!state.runId)return;const labels={pause:'Pause this extraction run?',resume:'Resume extraction?',cancel:'Cancel this extraction run? Messages not yet processed will remain queued.'};if(action==='cancel'&&!confirm(labels.cancel))return;try{const d=await api(`/api/runs/${state.runId}/${action}`,{method:'POST'});toast(d.message||`Run ${action} requested.`, 'success');await pollRun()}catch(e){toast(e.message,'error')}}
async function pollRun(){if(!state.runId)return;try{const d=await api(`/api/runs/${state.runId}`);const pct=d.total?Math.round((d.processed+d.failed)*100/d.total):0;const canPause=d.status==='running',canResume=d.status==='paused',canCancel=['queued','running','paused'].includes(d.status);const controls=`<div class="run-control-row">${canPause?'<button class="btn btn-secondary btn-sm" data-run-action="pause">Ⅱ Pause</button>':''}${canResume?'<button class="btn btn-primary btn-sm" data-run-action="resume">▶ Resume</button>':''}${canCancel?'<button class="btn btn-danger btn-sm" data-run-action="cancel">■ Stop</button>':''}</div>`;const html=`<div class="review-batch-progress-head"><b>Background extraction monitor</b><span class="tag ${['completed','completed_with_errors'].includes(d.status)?'green':d.status==='failed'||d.status==='cancelled'?'red':d.status==='paused'?'amber':'violet'}">${esc(d.status)}</span></div><div class="progress"><span style="width:${pct}%"></span></div><p class="muted" style="margin:9px 0">${d.processed}/${d.total} processed · ${d.failed} failed · ${Math.max(0,(d.total||0)-(d.processed||0)-(d.failed||0))} remaining</p>${controls}<div class="log-box">${(d.logs||[]).slice(-10).map(x=>`<div class="log-line">${esc(x.message)}</div>`).join('')}</div>`;const boxes=[$('#runProgress'),$('#reviewBatchRunLive'),$('#dashboardBatchRunLive')].filter(Boolean);boxes.forEach(box=>{box.innerHTML=html;box.querySelectorAll('[data-run-action]').forEach(btn=>btn.onclick=()=>controlBackgroundRun(btn.dataset.runAction))});const monitor=$('#globalRunMonitor');if(monitor){monitor.hidden=false;monitor.innerHTML=`<div class="global-run-head"><b>⚙ Background process · ${esc(d.kind||'Extraction')}</b><button class="icon-btn" id="hideRunMonitor" title="Hide monitor">×</button></div>${html}`;monitor.querySelector('#hideRunMonitor').onclick=()=>{monitor.hidden=true};monitor.querySelectorAll('[data-run-action]').forEach(btn=>btn.onclick=()=>controlBackgroundRun(btn.dataset.runAction))}if(['completed','completed_with_errors','failed','cancelled'].includes(d.status)){if(state.runPoll)clearInterval(state.runPoll);state.runPoll=null;state.review.lastBatchRun={status:d.status,processed:d.processed||0,failed:d.failed||0,total:d.total||0,logs:d.logs||[]};state.runId=null;await refreshWorkflow();toast(d.status==='cancelled'?`Extraction stopped: ${d.processed} completed; remaining messages kept queued.`:`Extraction finished: ${d.processed} processed, ${d.failed} failed`,d.failed?'error':'success');if(state.view==='review')renderReview();else if(state.view==='overview')renderOverview()}}catch(e){/* keep polling: a transient UI request must not stop a background run */}}

function renderBatchProcessAction(stats={},placement='review'){
  const summary=state.review.lastBatchRun;
  const eligible=Number(stats.queued||0),failed=Number(stats.failed||0),interrupted=Number(stats.interrupted||0),held=Number(stats.held||0);
  const dashboard=placement==='dashboard';
  const buttonId=dashboard?'dashboardProcessAll':'reviewProcessAll';
  const progressId=dashboard?'dashboardBatchRunLive':'reviewBatchRunProgress';
  const label=eligible?`▶ Process all ${compactNumber(eligible)} messages`:'No eligible messages to process';
  const statusLine=eligible?`${compactNumber(eligible-failed-interrupted)} queued · ${compactNumber(failed)} failed · ${compactNumber(interrupted)} interrupted`:'The batch queue is empty.';
  return `<section class="card review-batch-run-card ${dashboard?'dashboard-batch-run-card':''}"><div class="review-batch-run-copy"><span class="section-eyebrow">BATCH EXTRACTION · ONE-CLICK ACTION</span><h3>Process all queued messages</h3><p>One click sends every eligible message through the extraction engine. This is a one-time batch action and does not change your saved Live AI or one-by-one preference. Extracted results still enter human approval when approval is enabled.</p><div class="batch-eligibility-line"><b>${compactNumber(eligible)} eligible</b><span>${statusLine}</span>${held?`<span class="held-count">${compactNumber(held)} held by collection policy</span>`:''}</div></div><div class="review-batch-run-controls"><button class="btn btn-primary" id="${buttonId}" ${eligible?'':'disabled'}>${label}</button>${held?`<button class="btn btn-quiet btn-sm" data-nav="inbox">Inspect / requeue held messages ↗</button>`:''}<span class="muted">Includes queued, failed and interrupted messages · up to 10,000 per run. Held/filtered messages require requeueing first.</span></div><div id="${progressId}" class="review-batch-run-progress" aria-live="polite">${summary?renderBatchRunSummary(summary):''}</div></section>`;
}
function renderBatchRunSummary(summary){
  const pct=summary.total?Math.round((summary.processed+summary.failed)*100/summary.total):100;
  return `<div class="review-batch-progress-head"><b>Last batch run</b><span class="tag ${summary.status==='completed'?'green':summary.status==='failed'?'red':'amber'}">${esc(summary.status)}</span></div><div class="progress"><span style="width:${pct}%"></span></div><p class="muted" style="margin:9px 0">${summary.processed}/${summary.total} processed · ${summary.failed} failed</p>${summary.processed?`<button class="btn btn-secondary btn-sm" data-nav="review">Open Review Studio to approve extracted results one by one →</button>`:''}`;
}
function bindBatchProcessAction(){
  const button=$('#reviewProcessAll');if(button)button.onclick=()=>startExplicitBatchProcessing(button,'#reviewBatchRunProgress');
  const dashboardButton=$('#dashboardProcessAll');if(dashboardButton)dashboardButton.onclick=()=>startExplicitBatchProcessing(dashboardButton,'#dashboardBatchRunLive');
}
async function startExplicitBatchProcessing(button,progressSelector){
  if(state.runId){toast('An extraction run is already active. Wait for it to finish before starting another batch.','warning');return;}
  if(!button)return;
  const progress=$(progressSelector);const idleLabel=button.textContent;button.disabled=true;button.textContent='Starting batch extraction…';
  if(progress)progress.innerHTML='<div class="hint-box">Checking model readiness and starting the batch…</div>';
  try{
    const result=await api(`/api/workflows/${workflowId()}/process`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({include_processed:false,limit:10000,explicit_batch:true})});
    state.runId=result.run_id;state.review.lastBatchRun=null;
    if(progress)progress.innerHTML=`<div class="hint-box"><b>Batch started.</b> ${Number(result.total||0).toLocaleString()} eligible messages queued for extraction. Your saved Live AI preference has not changed.</div><div class="review-batch-run-live" id="reviewBatchRunLive"></div>`;
    toast(`Batch extraction started for ${result.total} queued messages.`, 'success');
    if(!state.runPoll)state.runPoll=setInterval(pollRun,1400);
    pollRun();
  }catch(error){
    if(progress)progress.innerHTML=`<div class="warning-box"><b>Batch was not started.</b><br>${esc(error.message||String(error))}</div>`;
    toast(error.message||'Batch extraction could not be started.','error');
  }finally{
    button.disabled=false;
    button.textContent=idleLabel;
  }
}

function renderStandaloneReviewLaunchCard(){
  return `<section class="card review-desktop-launch"><div class="review-desktop-launch-head"><div><span class="section-eyebrow">SEPARATE DESKTOP REVIEW APP</span><h3>Agent Shadi Review Desk <span class="tag green">Keyboard-first</span></h3><p>Open the full-screen reviewer in a new terminal window. One click here launches it on this computer; no launcher installation or command copying is needed.</p></div><div class="review-terminal-symbol">▣</div></div><div class="review-terminal-hotkeys"><span><kbd>↑</kbd><kbd>↓</kbd> Navigate</span><span><kbd>A</kbd> Approve</span><span><kbd>R</kbd> Reject</span><span><kbd>E</kbd> Edit</span><span><kbd>X</kbd> Extract (Live AI)</span><span><kbd>Space</kbd> Select</span><span><kbd>F2</kbd> Switch path</span></div><div class="review-desktop-launch-actions"><button class="btn btn-primary" id="launchReviewDesk"><span aria-hidden="true">↗</span> Open Review Desk</button><span class="muted" id="reviewDeskLaunchStatus" role="status">Uses the local Agent Shadi service and the same workflow database.</span></div><div class="hint-box">Both review paths support one-by-one human approval. Batch-extracted records wait for your decision; Live AI sends one raw message per LLM call. The Review Desk opens in a separate terminal window.</div></section>`;
}
function bindStandaloneReviewLaunchCard(){
  const button=$('#launchReviewDesk');if(!button)return;
  button.onclick=async()=>{
    const status=$('#reviewDeskLaunchStatus');button.disabled=true;button.innerHTML='<span class="spinner" aria-hidden="true"></span> Opening Review Desk…';
    if(status)status.textContent='Contacting the local desktop service…';
    try{
      const result=await api('/api/review/launch',{method:'POST'});
      if(!result.verified)throw new Error(result.message||'The terminal did not confirm that the Review Desk initialized.');
      if(status)status.textContent=`Review Desk initialized in ${result.terminal||'a new terminal window'}.`;
      toast('Agent Shadi Review Desk is open and ready.','success');
    }catch(error){
      if(status)status.textContent=error.message||'Could not open the Review Desk.';
      toast(error.message||'Could not open the Review Desk.','error');
    }finally{
      button.disabled=false;button.innerHTML='<span aria-hidden="true">↗</span> Open Review Desk';
    }
  };
}

async function renderReview(){
  const cfg=state.config||{};const settings=cfg.review_settings||{mode:'guided',processing_path:'processed',auto_advance:true,confirm_bulk:true,page_size:100,sort:'newest'};
  const batchWorkflow=await api(`/api/workflows/${workflowId()}`);const batchStats=batchWorkflow.counts||{};
  const rstate=state.review;rstate.mode=settings.mode||rstate.mode||'guided';rstate.settings=settings;rstate.path=settings.processing_path||rstate.path||'processed';
  if(rstate.path==='live'){await renderLiveReview(settings);return;}
  const data=await api(`/api/workflows/${workflowId()}/review/queue?limit=${settings.page_size||100}&offset=${rstate.offset||0}&q=${encodeURIComponent(rstate.query||'')}&source=${encodeURIComponent(rstate.source||'all')}&issue=${encodeURIComponent(rstate.issue||'all')}&sort=${encodeURIComponent(rstate.sort||settings.sort||'newest')}`);
  rstate.items=data.items||[];rstate.sources=data.sources||[];rstate.summary=data.summary||{};rstate.total=data.total||0;rstate.totalReview=data.total_review||0;rstate.hasMore=!!data.has_more;rstate.pageSize=data.limit||100;rstate.enabled=data.review_enabled!==false;
  if(rstate.awaitingAdvance){
    // Preserve the next-row target after an approval/rejection while the chosen
    // item disappears from the pending queue. Do not collapse the target to 0.
    rstate.selectedId=null;
    rstate.position=Math.max(0,Math.min(Number(rstate.position)||0,Math.max(0,rstate.items.length-1)));
  }else{
    if(!rstate.items.some(x=>x.id===rstate.selectedId))rstate.selectedId=rstate.items[Math.min(rstate.position||0,Math.max(0,rstate.items.length-1))]?.id||rstate.items[0]?.id||null;
    rstate.position=Math.max(0,rstate.items.findIndex(x=>x.id===rstate.selectedId));
  }
  const current=rstate.items.find(x=>x.id===rstate.selectedId)||null;
  const selectedCount=rstate.selected.size;
  const modeLabel=rstate.mode==='guided'?'GUIDED REVIEW':'BATCH REVIEW';
  $('#view-review').innerHTML=`${pageHead('HUMAN-IN-THE-LOOP','Review Studio','Inspect original messages and structured output side by side. Approve extracted records one by one or use batch mode. For keyboard-first work, launch the separate Review Desk.',`<button class="btn btn-secondary" data-nav="learning">Corrections library</button>${rstate.undoToken?'<button class="btn btn-quiet" id="reviewUndo">↶ Undo last action</button>':''}`)}
  ${renderReviewPathSwitch('processed')}
  ${renderBatchProcessAction(batchStats,'review')}
  <section class="review-overview-strip">
    <div class="review-kpi"><small>Awaiting review</small><b>${rstate.totalReview}</b><span>Unapproved records</span></div>
    <div class="review-kpi"><small>In this view</small><b>${rstate.total}</b><span>After filters</span></div>
    <div class="review-kpi"><small>Warnings</small><b>${rstate.summary.warnings||0}</b><span>Need attention</span></div>
    <div class="review-kpi"><small>Low confidence</small><b>${rstate.summary.low_confidence||0}</b><span>Below 55%</span></div>
    <div class="review-mode-card"><div><small>Approval requirement</small><b>${rstate.enabled?'Human approval ON':'Automatic approval ON'}</b><span>${rstate.enabled?'New valid results wait for your decision.':'New valid results are approved automatically; validation errors still wait.'}</span></div><label class="review-switch"><input id="reviewApprovalToggle" type="checkbox" ${rstate.enabled?'checked':''}><i></i></label></div>
  </section>
  <section class="review-toolbar card"><div class="review-toolbar-main"><div><span class="section-eyebrow">REVIEW WORKSPACE</span><h3>${modeLabel} <span class="tag ${rstate.mode==='guided'?'violet':'green'}">${rstate.mode==='guided'?'One at a time':'Multi-select'}</span></h3></div><div class="review-toolbar-controls"><div class="segmented-control"><button data-review-mode="guided" class="${rstate.mode==='guided'?'active':''}">Guided</button><button data-review-mode="batch" class="${rstate.mode==='batch'?'active':''}">Batch</button></div><select id="reviewSort" class="input small"><option value="newest" ${rstate.sort==='newest'?'selected':''}>Newest first</option><option value="oldest" ${rstate.sort==='oldest'?'selected':''}>Oldest first</option><option value="confidence_low" ${rstate.sort==='confidence_low'?'selected':''}>Lowest confidence</option><option value="confidence_high" ${rstate.sort==='confidence_high'?'selected':''}>Highest confidence</option><option value="errors_first" ${rstate.sort==='errors_first'?'selected':''}>Errors first</option></select><select id="reviewPageSize" class="input small" aria-label="Rows per page"><option value="50" ${Number(settings.page_size||100)===50?'selected':''}>50 / page</option><option value="100" ${Number(settings.page_size||100)===100?'selected':''}>100 / page</option><option value="250" ${Number(settings.page_size||100)===250?'selected':''}>250 / page</option><option value="500" ${Number(settings.page_size||100)===500?'selected':''}>500 / page</option></select><label class="review-auto-advance"><input id="reviewStudioAutoAdvance" type="checkbox" ${settings.auto_advance!==false?'checked':''}><span>Auto-advance</span></label><label class="review-auto-advance"><input id="reviewConfirmBulk" type="checkbox" ${settings.confirm_bulk!==false?'checked':''}><span>Confirm bulk</span></label></div></div>
    <div class="review-filter-row"><input id="reviewSearch" class="input" placeholder="Search original text, fields, source…" value="${esc(rstate.query)}"><select id="reviewIssue" class="input small"><option value="all" ${rstate.issue==='all'?'selected':''}>All items</option><option value="errors" ${rstate.issue==='errors'?'selected':''}>Has errors</option><option value="warnings" ${rstate.issue==='warnings'?'selected':''}>Has warnings</option><option value="low_confidence" ${rstate.issue==='low_confidence'?'selected':''}>Low confidence</option><option value="missing_required" ${rstate.issue==='missing_required'?'selected':''}>Missing required</option></select><select id="reviewSource" class="input small"><option value="all">All sources</option>${rstate.sources.map(x=>`<option value="${esc(x)}" ${rstate.source===x?'selected':''}>${esc(x)}</option>`).join('')}</select><button class="btn btn-secondary btn-sm" id="reviewSearchApply">Apply filters</button><button class="btn btn-quiet btn-sm" id="reviewFiltersClear">Clear</button></div>
    <div class="review-bulk-row"><div class="review-position">${rstate.total?`Showing ${rstate.offset+1}–${rstate.offset+rstate.items.length} of ${rstate.total} filtered · ${rstate.totalReview} waiting total`:'No records match this view'}</div><div class="review-bulk-actions"><span class="tag">${selectedCount} selected</span><button class="btn btn-success btn-sm" id="reviewApproveSelected" ${selectedCount?'':'disabled'}>✓ Approve selected</button><button class="btn btn-danger btn-sm" id="reviewRejectSelected" ${selectedCount?'':'disabled'}>× Reject selected</button></div></div>
  </section>
  <section class="review-studio-grid">
    <aside class="card review-queue-panel"><div class="review-panel-head"><div><span class="section-eyebrow">NUMBERED QUEUE</span><h3>Records <span class="tag amber">${rstate.total}</span></h3></div><div class="review-page-controls"><button class="btn btn-quiet btn-sm" id="reviewPrevPage" ${rstate.offset<=0?'disabled':''}>‹</button><button class="btn btn-quiet btn-sm" id="reviewNextPage" ${!rstate.hasMore?'disabled':''}>›</button></div></div><div class="review-queue-list" id="reviewQueueList">${renderReviewQueueItems(rstate.items,rstate.selectedId,rstate.offset,rstate.selected,rstate.mode)}</div><div class="review-queue-foot"><small>For fast keyboard-first review, launch Agent Shadi Review Desk in its own terminal window.</small></div></aside>
    <div class="review-detail-column">${current?renderReviewDetail(current,rstate.offset+rstate.position+1,rstate.total):rstate.awaitingAdvance?`<section class="card review-detail-card review-awaiting-advance"><span class="section-eyebrow">DECISION SAVED</span><h2>Ready for the next record?</h2><p>Your last decision has been saved. Guided auto-advance is disabled, so you control when the next item opens.</p><button class="btn btn-primary" id="reviewContinueNext">Continue to next record →</button></section>`:empty('Review queue is clear','No records are waiting for approval. Run extraction or change the filters to inspect other records.','✓')}
    ${renderStandaloneReviewLaunchCard()}
    </div>
  </section>`;
  // List selection and batch checkboxes.
  $$('.review-queue-item').forEach(el=>el.onclick=(ev)=>{if(ev.target.closest('.review-select-check'))return;rstate.selectedId=el.dataset.id;rstate.position=Number(el.dataset.index);rstate.awaitingAdvance=false;renderReview()});
  $$('.review-select-check').forEach(ch=>ch.onchange=()=>{if(ch.checked)rstate.selected.add(ch.value);else rstate.selected.delete(ch.value);renderReview()});
  $('#reviewContinueNext')?.addEventListener('click',()=>moveReviewSelection(1));
  $$('.review-queue-item').forEach(el=>el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();rstate.selectedId=el.dataset.id;rstate.position=Number(el.dataset.index);rstate.awaitingAdvance=false;renderReview();}});
  $('#reviewEditCurrent')?.addEventListener('click',()=>openRecordEditor(current));
  $('#reviewPrevRecord')?.addEventListener('click',()=>moveReviewSelection(-1));
  $('#reviewSkipRecord')?.addEventListener('click',()=>moveReviewSelection(1));
  $('#reviewApproveCurrent')?.addEventListener('click',()=>current&&executeReviewAction([current.id],'approve'));
  $('#reviewRejectCurrent')?.addEventListener('click',()=>current&&executeReviewAction([current.id],'reject'));
  $('#reviewApprovalToggle').onchange=async()=>{const enabled=$('#reviewApprovalToggle').checked;if(!enabled&&!confirm('Turn off mandatory human approval for NEW extraction results? Existing pending records will remain in Review Studio. Validation errors will still require review.')){renderReview();return;}await saveReviewSettings({enabled});};
  $$('[data-review-mode]').forEach(b=>b.onclick=()=>saveReviewSettings({enabled:rstate.enabled,mode:b.dataset.reviewMode}));
  $('#reviewSort').onchange=()=>{rstate.sort=$('#reviewSort').value;rstate.offset=0;rstate.selected.clear();saveReviewSettings({enabled:rstate.enabled,mode:rstate.mode,sort:rstate.sort})};
  $('#reviewPageSize').onchange=()=>{rstate.offset=0;rstate.selected.clear();saveReviewSettings({enabled:rstate.enabled,mode:rstate.mode,page_size:Number($('#reviewPageSize').value)})};
  $('#reviewStudioAutoAdvance').onchange=()=>saveReviewSettings({enabled:rstate.enabled,mode:rstate.mode,auto_advance:$('#reviewStudioAutoAdvance').checked});
  $('#reviewConfirmBulk').onchange=()=>saveReviewSettings({enabled:rstate.enabled,mode:rstate.mode,confirm_bulk:$('#reviewConfirmBulk').checked});
  $('#reviewSearchApply').onclick=()=>{rstate.query=$('#reviewSearch').value.trim();rstate.issue=$('#reviewIssue').value;rstate.source=$('#reviewSource').value;rstate.offset=0;rstate.selected.clear();renderReview()};
  $('#reviewSearch').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('#reviewSearchApply').click()}};
  $('#reviewIssue').onchange=()=>{rstate.issue=$('#reviewIssue').value;rstate.offset=0;rstate.selected.clear();renderReview()};
  $('#reviewSource').onchange=()=>{rstate.source=$('#reviewSource').value;rstate.offset=0;rstate.selected.clear();renderReview()};
  $('#reviewFiltersClear').onclick=()=>{rstate.query='';rstate.issue='all';rstate.source='all';rstate.offset=0;rstate.selected.clear();renderReview()};
  $('#reviewPrevPage').onclick=()=>{rstate.offset=Math.max(0,rstate.offset-rstate.pageSize);rstate.selected.clear();renderReview()};
  $('#reviewNextPage').onclick=()=>{rstate.offset+=rstate.pageSize;rstate.selected.clear();rstate.selectedId=null;renderReview()};
  $('#reviewApproveSelected').onclick=()=>executeReviewAction([...rstate.selected],'approve');
  $('#reviewRejectSelected').onclick=()=>executeReviewAction([...rstate.selected],'reject');
  bindStandaloneReviewLaunchCard();
  bindBatchProcessAction();
  $$('[data-review-path]').forEach(b=>b.onclick=()=>switchReviewPath(b.dataset.reviewPath));
  if($('#reviewUndo'))$('#reviewUndo').onclick=undoReviewLast;
  bindReviewKeyboard();
}
function renderReviewPathSwitch(active){
  return `<div class="review-path-switch card"><div><span class="section-eyebrow">HOW SHOULD SHADI PROCESS?</span><b>Choose your review pipeline</b><small>Switch between reviewing completed AI output and sending each raw message to the model only when you reach it.</small></div><div class="review-path-options"><button data-review-path="processed" class="${active==='processed'?'active':''}"><span>✧</span><b>Review extracted results</b><small>AI has already processed these messages</small></button><button data-review-path="live" class="${active==='live'?'active':''}"><span>◉</span><b>Live AI · one by one</b><small>Send each selected message to AI on demand</small></button></div></div>`;
}
async function switchReviewPath(path){
  if(!['processed','live'].includes(path))return;
  const r=state.review;
  if(r.liveRecord&&path!=='live'&&!confirm('An extracted live-review record is still awaiting your decision. It will remain safely in the normal Review Queue. Switch paths?'))return;
  r.path=path;r.offset=0;r.position=0;r.selectedId=null;r.awaitingAdvance=false;r.selected.clear();
  r.liveRecord=null;r.liveMessage=null;r.liveMessageId=null;
  await saveReviewSettings({enabled:r.enabled,mode:r.mode,processing_path:path});
}
function renderLiveQueueItems(items,selectedId,offset){
  if(!items.length)return empty('No raw messages are waiting','The live queue is empty. Import or collect more messages, or switch to Review extracted results to inspect records already processed by AI.','◉');
  return items.map((m,i)=>{const n=offset+i+1;const issue=m.status==='failed'?'error':m.status==='interrupted'?'warning':'clean';return `<div role="button" tabindex="0" class="review-queue-item ${m.id===selectedId?'active':''}" data-live-id="${m.id}" data-index="${i}"><span class="review-row-number">${n}</span><span class="review-queue-copy"><b>${esc((m.raw_text||'').replace(/\s+/g,' ').slice(0,78)||'Empty source message')}</b><small>${esc(m.source||'Unknown source')} · ${esc(m.posted_at||'No date')}</small><span class="review-queue-tags"><i class="${issue}"></i>${esc(m.status)}${m.error?` · ${esc(m.error.slice(0,90))}`:''}</span></span></div>`}).join('');
}
function renderLiveProgress(progress){
  const host=$('#liveExtractionProgress');if(!host)return;
  if(!progress||!['processing','completed','failed'].includes(progress.status)){host.innerHTML='';return;}
  const labels=[['checking_model','Check model'],['preparing','Prepare message'],['waiting_for_model','AI response'],['validating','Validate output'],['saving','Save result']];
  const order=labels.findIndex(x=>x[0]===progress.phase);
  const heading=progress.status==='completed'?'Extraction complete':progress.status==='failed'?(progress.phase==='recovery'?'Previous attempt interrupted':'Extraction failed'):'Agent Shadi is processing this message';
  host.innerHTML=`<div class="live-extraction-progress ${progress.status==='failed'?'failed':progress.status==='completed'?'complete':''}" role="status" aria-live="polite"><div class="live-progress-top"><b>${heading}</b><span>${progress.status==='processing'?`${Math.max(0,Math.min(100,Number(progress.percent)||0))}%`:progress.status==='completed'?'100%':'Attention'}</span></div><div class="live-progress-track"><i style="width:${Math.max(0,Math.min(100,Number(progress.percent)||0))}%"></i></div><p>${esc(progress.message||'Working…')}</p><div class="live-progress-steps">${labels.map((step,i)=>`<span class="${progress.status==='completed'||(order>=0&&i<order)?'done':i===order?'active':''}">${i+1}. ${step[1]}</span>`).join('')}</div></div>`;
}
function stopLiveProgressPolling(){const r=state.review;if(r.liveProgressTimer){clearInterval(r.liveProgressTimer);r.liveProgressTimer=null;}r.liveProgressMessageId=null;}
function startLiveProgressPolling(messageId){
  const r=state.review;
  if(r.liveProgressTimer&&r.liveProgressMessageId===messageId)return;
  stopLiveProgressPolling();r.liveProgressMessageId=messageId;
  let pending=false,terminalHandled=false;
  const poll=async()=>{
    if(pending)return;pending=true;
    try{
      const p=await api(`/api/workflows/${workflowId()}/review/live/${messageId}/progress`);
      if(state.view!=='review'||r.path!=='live'||r.selectedId!==messageId){stopLiveProgressPolling();return;}
      r.liveProgress=p;renderLiveProgress(p);
      if(p.status==='completed'||p.status==='failed'){
        stopLiveProgressPolling();
        if(!terminalHandled){terminalHandled=true;await renderReview();}
      }
    }catch(e){}finally{pending=false;}
  };
  // Let the extraction POST begin and publish its first server-side phase
  // before the first poll; otherwise an instant idle GET can erase the local state.
  r.liveProgressTimer=setInterval(poll,900);
}
function renderLiveMessageDetail(m,position,total,progress=null){
  const processing=m.status==='processing'||progress?.status==='processing';
  const failed=m.status==='failed'||m.status==='interrupted'||progress?.status==='failed';
  const ready=(state.modelHealth||{}).status==='online';
  const heading=processing?'Extraction in progress':failed?'Extraction needs attention':'Ready for AI extraction';
  const action=processing?'Processing…':failed?'Retry with AI':'Extract this message';
  return `<section class="card review-detail-card live-message-card"><div class="review-detail-head"><div><span class="section-eyebrow">LIVE SOURCE ${position} / ${total}</span><h2>${heading}</h2><div class="review-meta"><span>${esc(m.source||'Unknown source')}</span><span>${esc(m.posted_at||'Date unavailable')}</span><span>${esc(m.status||'queued')}</span></div></div><span class="tag ${failed?'red':processing?'amber':'violet'}">${failed?'ATTENTION REQUIRED':processing?'AI WORKING':'READY'}</span></div><div class="review-source-panel"><div class="review-section-title"><b>Original source message</b><span>Source text remains unchanged</span></div><div class="review-original-text">${esc(m.raw_text||'')}</div><div class="review-source-meta"><span>Source reference</span><b>${esc(m.source_ref||'Not provided')}</b></div></div>${m.error&&!processing?`<div class="review-alert error">Previous attempt: ${esc(m.error)}</div>`:''}<div id="liveExtractionProgress"></div><div class="live-ai-action"><div><b>${processing?'Working on the selected message':failed?'Review the error and retry':'Send this message to your configured model'}</b><small>${processing?'The message is claimed and will remain visible until the result is saved. Do not switch review paths while this request is running.':'Only this message is sent to the LLM. Its result enters Needs Review; nothing is automatically approved.'}</small></div><button class="btn btn-primary" id="liveExtractCurrent" ${processing||!ready?'disabled':''}>✦ ${action}</button></div></section>`;
}
async function renderLiveReview(settings){
  const r=state.review;r.enabled=state.config?.review_mode!==false;const pageSize=Math.max(10,Math.min(500,Number(settings.page_size)||50));
  const batchWorkflow=await api(`/api/workflows/${workflowId()}`);const batchStats=batchWorkflow.counts||{};
  const data=await api(`/api/workflows/${workflowId()}/review/live/queue?limit=${pageSize}&offset=${r.offset||0}&q=${encodeURIComponent(r.query||'')}&source=${encodeURIComponent(r.source||'all')}`);
  r.items=data.items||[];r.total=data.total||0;r.hasMore=!!data.has_more;r.pageSize=data.limit||pageSize;r.sources=data.sources||[];r.liveExtractedWaiting=data.extracted_waiting||0;
  const activeRecord=!!(r.liveRecord&&r.liveMessage&&r.liveRecord.message_id===r.liveMessage.id);
  if(!activeRecord&&!r.awaitingAdvance){
    if(!r.items.some(x=>x.id===r.selectedId))r.selectedId=r.items[Math.min(r.position||0,Math.max(0,r.items.length-1))]?.id||r.items[0]?.id||null;
    r.position=Math.max(0,r.items.findIndex(x=>x.id===r.selectedId));
  }
  const current=activeRecord?r.liveMessage:(r.awaitingAdvance?null:r.items.find(x=>x.id===r.selectedId)||null);
  const position=activeRecord?r.livePosition:(r.offset+r.position+1);
  let detail='';
  if(activeRecord)detail=renderReviewDetail(r.liveRecord,position,r.total+r.liveExtractedWaiting);
  else if(r.awaitingAdvance)detail=`<section class="card review-detail-card review-awaiting-advance"><span class="section-eyebrow">DECISION SAVED</span><h2>Ready for the next message?</h2><p>Your last AI result was approved or rejected. Manual advance is enabled, so Shadi will wait for your instruction.</p><button class="btn btn-primary" id="reviewContinueNext">Continue to next raw message →</button></section>`;
  else if(current){
    try{const progress=await api(`/api/workflows/${workflowId()}/review/live/${current.id}/progress`);r.liveProgress=progress.status==='idle'?null:progress;}
    catch(e){r.liveProgress=current.status==='processing'?{status:'processing',phase:'waiting_for_model',message:'Checking extraction progress…',percent:35}:null;}
    detail=renderLiveMessageDetail(current,position,r.total,r.liveProgress)
  }
  else detail=empty('Live queue is clear','There are no unprocessed messages available for live AI review.','✓');
  $('#view-review').innerHTML=`${pageHead('HUMAN-IN-THE-LOOP','Review Studio · Live AI','Choose each raw message, send it to your LLM individually, inspect the structured result, and approve or reject before moving on.',`<button class="btn btn-secondary" data-nav="builder">Extraction schema</button><button class="btn btn-quiet" data-nav="settings">Model settings</button>`)}
  ${renderReviewPathSwitch('live')}
  ${renderBatchProcessAction(batchStats,'review')}
  <section class="review-overview-strip"><div class="review-kpi"><small>Raw messages waiting</small><b>${r.total}</b><span>Not yet sent to AI</span></div><div class="review-kpi"><small>Already extracted</small><b>${r.liveExtractedWaiting}</b><span>Waiting in standard review</span></div><div class="review-kpi"><small>Current source</small><b>${current?esc(current.source||'Unknown'): '—'}</b><span>Selected message</span></div><div class="review-kpi"><small>Model status</small><b class="live-model-state ${state.modelHealth?.status==='online'?'online':'offline'}">${esc(state.modelHealth?.status||'Not checked')}</b><span>${esc(state.modelHealth?.model||'Configure a model')}</span></div><div class="review-mode-card"><div><small>After a decision</small><b>${settings.auto_advance===false?'Manual advance':'Auto-advance'}</b><span>${settings.auto_advance===false?'Wait for your next command':'Select next raw message automatically'}</span></div><label class="review-switch"><input id="reviewStudioAutoAdvance" type="checkbox" ${settings.auto_advance!==false?'checked':''}><i></i></label></div></section>
  <section class="review-toolbar card"><div class="review-toolbar-main"><div><span class="section-eyebrow">SEQUENTIAL LLM PROCESSING</span><h3>Live AI queue <span class="tag violet">One message per call</span></h3></div><div class="review-toolbar-controls"><select id="reviewPageSize" class="input small"><option value="50" ${pageSize===50?'selected':''}>50 / page</option><option value="100" ${pageSize===100?'selected':''}>100 / page</option><option value="250" ${pageSize===250?'selected':''}>250 / page</option><option value="500" ${pageSize===500?'selected':''}>500 / page</option></select><label class="review-auto-advance"><input id="reviewConfirmBulk" type="checkbox" ${settings.confirm_bulk!==false?'checked':''}><span>Confirm decisions</span></label></div></div><div class="review-filter-row"><input id="reviewSearch" class="input" value="${esc(r.query||'')}" placeholder="Search raw message, source or reference"><select id="reviewSource" class="input"><option value="all">All sources</option>${r.sources.map(x=>`<option value="${esc(x)}" ${r.source===x?'selected':''}>${esc(x)}</option>`).join('')}</select><button id="reviewSearchApply" class="btn btn-secondary">Apply</button><button id="reviewFiltersClear" class="btn btn-quiet">Clear filters</button></div></section>
  <section class="review-studio-grid"><aside class="card review-queue-panel"><div class="review-panel-head"><div><span class="section-eyebrow">RAW MESSAGE QUEUE</span><h3>Messages <span class="tag amber">${r.total}</span></h3></div><div class="review-page-controls"><button class="btn btn-quiet btn-sm" id="reviewPrevPage" ${r.offset<=0?'disabled':''}>‹</button><button class="btn btn-quiet btn-sm" id="reviewNextPage" ${!r.hasMore?'disabled':''}>›</button></div></div><div class="review-queue-list">${renderLiveQueueItems(r.items,r.selectedId,r.offset)}</div><div class="review-queue-foot"><small>Processing messages stay visible here while Agent Shadi works. Results are saved for human review.</small></div></aside><div class="review-detail-column">${detail}${renderStandaloneReviewLaunchCard()}</div></section>`;
  $$('[data-review-path]').forEach(b=>b.onclick=()=>switchReviewPath(b.dataset.reviewPath));
  $$('.review-queue-item[data-live-id]').forEach(el=>{el.onclick=()=>{if(r.liveRecord){toast('Approve or reject the current extracted result first. It will remain available in Review extracted results.','info');return;}r.selectedId=el.dataset.liveId;r.position=Number(el.dataset.index);r.awaitingAdvance=false;renderReview()};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click()}}});
  $('#liveExtractCurrent')?.addEventListener('click',()=>current&&runLiveExtraction(current.id));
  if(activeRecord){$('#reviewEditCurrent')?.addEventListener('click',()=>openRecordEditor(r.liveRecord));$('#reviewApproveCurrent')?.addEventListener('click',()=>executeReviewAction([r.liveRecord.id],'approve'));$('#reviewRejectCurrent')?.addEventListener('click',()=>executeReviewAction([r.liveRecord.id],'reject'));$('#reviewPrevRecord')?.addEventListener('click',()=>toast('The previous message remains available in the processed review queue.','info'));$('#reviewSkipRecord')?.addEventListener('click',()=>toast('Approve or reject this extraction before continuing.','info'));}
  $('#reviewContinueNext')?.addEventListener('click',()=>moveReviewSelection(1));
  $('#reviewStudioAutoAdvance').onchange=()=>saveReviewSettings({enabled:r.enabled,mode:r.mode,processing_path:'live',auto_advance:$('#reviewStudioAutoAdvance').checked});
  $('#reviewConfirmBulk').onchange=()=>saveReviewSettings({enabled:r.enabled,mode:r.mode,processing_path:'live',confirm_bulk:$('#reviewConfirmBulk').checked});
  $('#reviewPageSize').onchange=()=>saveReviewSettings({enabled:r.enabled,mode:r.mode,processing_path:'live',page_size:Number($('#reviewPageSize').value)});
  $('#reviewSearchApply').onclick=()=>{r.query=$('#reviewSearch').value.trim();r.source=$('#reviewSource').value;r.offset=0;r.selectedId=null;r.selected.clear();renderReview()};
  $('#reviewSearch').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('#reviewSearchApply').click()}};
  $('#reviewSource').onchange=()=>{r.source=$('#reviewSource').value;r.offset=0;r.selectedId=null;renderReview()};
  $('#reviewFiltersClear').onclick=()=>{r.query='';r.source='all';r.offset=0;r.selectedId=null;renderReview()};
  $('#reviewPrevPage').onclick=()=>{r.offset=Math.max(0,r.offset-r.pageSize);r.selectedId=null;renderReview()};
  $('#reviewNextPage').onclick=()=>{r.offset+=r.pageSize;r.selectedId=null;renderReview()};
  bindStandaloneReviewLaunchCard();
  bindBatchProcessAction();
  bindReviewKeyboard();
  if(current&&current.status==='processing')startLiveProgressPolling(current.id);
  else if(r.liveProgressTimer)stopLiveProgressPolling();
}
async function runLiveExtraction(messageId){
  const r=state.review;const message=r.items.find(x=>x.id===messageId)||r.liveMessage;
  if(!message){toast('Select a raw message first.','error');return;}
  stopLiveProgressPolling();
  r.liveProgress={status:'processing',phase:'checking_model',percent:3,message:'Checking the configured model. The selected message is not being changed yet…'};
  message.status='processing';
  const button=$('#liveExtractCurrent');if(button){button.disabled=true;button.textContent='Processing…';}
  const status=$('#reviewCommandState');if(status)status.textContent='AI RUNNING';
  renderLiveProgress(r.liveProgress);
  startLiveProgressPolling(messageId);
  try{
    const result=await api(`/api/workflows/${workflowId()}/review/live/${messageId}/extract`,{method:'POST'});
    stopLiveProgressPolling();
    r.liveProgress={status:'completed',phase:'completed',percent:100,message:'Extraction saved. The structured result is ready for your review.'};
    r.liveMessage=message;r.liveMessageId=messageId;r.liveRecord=result.record;r.livePosition=r.offset+Math.max(0,r.items.findIndex(x=>x.id===messageId))+1;r.selectedId=messageId;r.awaitingAdvance=false;
    logReviewCommand(`extract ${r.livePosition}`,`LLM extraction completed. ${Object.keys(result.record.data||{}).length} field(s); record is waiting for your decision.`);
    await refreshWorkflow();await renderReview();
  }catch(e){
    stopLiveProgressPolling();
    r.liveProgress={status:'failed',phase:'failed',percent:100,message:e.message};
    renderLiveProgress(r.liveProgress);logReviewCommand(`extract ${messageId}`,e.message,true);toast(e.message,'error');
    if(button){button.disabled=false;button.textContent='Retry with AI';}if(status)status.textContent='ERROR';
    // Refresh the raw queue so an interrupted/retryable message is not left looking active.
    await renderReview().catch(()=>{});
  }
}

function renderReviewQueueItems(items,selectedId,offset,selected,mode){
  if(!items.length)return empty('Nothing to review','Try clearing the filters or run another extraction.','✓');
  return items.map((r,i)=>{const n=offset+i+1,primary=Object.values(r.data||{}).filter(v=>v!==null&&v!=='').slice(0,2).join(' · ')||'Unclassified record';const flags=(r.errors||[]).length?'error':(r.warnings||[]).length?'warning':'clean';return `<div role="button" tabindex="0" class="review-queue-item ${r.id===selectedId?'active':''}" data-id="${r.id}" data-index="${i}"><span class="review-row-number">${n}</span>${mode==='batch'?`<input class="review-select-check" type="checkbox" value="${r.id}" ${selected.has(r.id)?'checked':''} aria-label="Select row ${n}">`:''}<span class="review-queue-copy"><b>${esc(primary)}</b><small>${esc(r.source||'Unknown source')} · ${esc(r.posted_at||'No date')}</small><span class="review-queue-tags"><i class="${flags}"></i>${Math.round((r.confidence||0)*100)}% confidence ${(r.errors||[]).length?`· ${(r.errors||[]).length} errors`:''}</span></span></div>`}).join('');
}
function renderReviewDetail(r,position,total){
  const fields=Object.entries(r.data||{}).map(([key,value])=>`<div class="review-field-card"><small>${esc(key)}</small><b>${esc(value===null?'—':typeof value==='object'?JSON.stringify(value):value)}</b><em>${esc(r.provenance?.[key]||'No provenance provided')}</em></div>`).join('');
  const warnings=(r.warnings||[]).map(x=>`<div class="review-alert warning">${esc(x)}</div>`).join('');const errors=(r.errors||[]).map(x=>`<div class="review-alert error">${esc(x)}</div>`).join('');
  return `<section class="card review-detail-card"><div class="review-detail-head"><div><span class="section-eyebrow">RECORD ${position} / ${total}</span><h2>${esc(Object.values(r.data||{}).filter(Boolean).slice(0,2).join(' · ')||'Unclassified record')}</h2><div class="review-meta"><span>${esc(r.source||'Unknown source')}</span><span>${esc(r.posted_at||'Date unavailable')}</span><span>${esc(r.engine||'Extraction engine')}</span><span>Confidence ${Math.round((r.confidence||0)*100)}%</span></div></div><span class="tag amber">NEEDS REVIEW</span></div><div class="review-decision-bar"><button class="btn btn-secondary" id="reviewEditCurrent">✎ Edit fields</button><button class="btn btn-quiet" id="reviewPrevRecord" ${position<=1?'disabled':''}>← Previous</button><button class="btn btn-quiet" id="reviewSkipRecord">Skip</button><button class="btn btn-danger" id="reviewRejectCurrent">Reject</button><button class="btn btn-success" id="reviewApproveCurrent">✓ Approve ${state.review.mode==='guided'&&state.review.settings?.auto_advance!==false?'& next':''}</button></div><div class="review-detail-grid"><div class="review-source-panel"><div class="review-section-title"><b>Original source message</b><span>Immutable evidence</span></div><div class="review-original-text">${esc(r.raw_text||'Original message unavailable')}</div><div class="review-source-meta"><span>Source reference</span><b>${esc(r.source_ref||'Not provided')}</b></div></div><div class="review-output-panel"><div class="review-section-title"><b>Structured extraction</b><span>${Object.keys(r.data||{}).length} fields</span></div><div class="review-fields-grid">${fields||empty('No extracted fields','Edit this record or inspect its original source.')}</div></div></div>${errors}${warnings}<div class="review-detail-footer"><span>Record ID <code>${esc(r.id)}</code></span><span>Created ${esc((r.created_at||'').slice(0,19).replace('T',' '))}</span></div></section>`;
}
function logReviewCommand(command,result,error=false){const h=state.review.history;h.push({command,result,error});if(h.length>30)h.splice(0,h.length-30)}
function parseReviewSelection(spec){const r=state.review,items=r.items;const first=r.offset+1,last=r.offset+items.length;const indexes=new Set();for(const part of String(spec||'').split(',')){const m=part.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!m)throw new Error(`Invalid row selection: ${part}`);const a=Number(m[1]),b=Number(m[2]||m[1]);if(a<first||b<a||b>last||b-a>499)throw new Error(`Choose visible row numbers between ${first} and ${last}.`);for(let n=a;n<=b;n++)indexes.add(n-first);}return [...indexes].sort((a,b)=>a-b).map(i=>items[i].id)}
async function executeReviewAction(ids,action){const rstate=state.review;ids=[...new Set(ids)].filter(Boolean);if(!ids.length){toast('Select at least one visible review row.','error');return;}if(action==='reject'&&ids.length===1&&!confirm('Reject this record? It will be excluded from approved exports. You can undo this action.'))return;if(ids.length>1&&rstate.settings?.confirm_bulk!==false&&!confirm(`${action==='approve'?'Approve':'Reject'} ${ids.length} selected records? ${action==='reject'?'They will be excluded from approved exports. ':''}This batch can be undone.`))return;const oldPosition=rstate.position;try{let result;if(ids.length===1){result=await api(`/api/records/${ids[0]}/${action}`,action==='reject'?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason:'Rejected from Review Studio'})}:{method:'POST'});}else{result=await api(`/api/workflows/${workflowId()}/records/bulk-action`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids,action,reason:`Batch ${action} from Review Studio`})});}rstate.undoToken=result.undo_token||rstate.undoToken;if(rstate.liveRecord&&ids.includes(rstate.liveRecord.id)){rstate.liveRecord=null;rstate.liveMessage=null;rstate.liveMessageId=null;}ids.forEach(id=>rstate.selected.delete(id));if(rstate.mode==='guided'&&rstate.settings?.auto_advance===false){rstate.awaitingAdvance=true;rstate.selectedId=null;}else{rstate.awaitingAdvance=false;rstate.selectedId=null;}logReviewCommand(`${action} ${ids.length===1?state.review.items.find(x=>x.id===ids[0])?(state.review.offset+state.review.items.findIndex(x=>x.id===ids[0])+1):'record':'selected'}`,`${result.updated??1} record(s): ${action==='approve'?'approved':'rejected'}.`);rstate.position=oldPosition;await renderReview();await refreshWorkflow();}catch(e){logReviewCommand(action,e.message,true);toast(e.message,'error')}}
async function moveReviewSelection(delta){
  const r=state.review;if(r.path==='live'&&r.liveRecord){toast('Approve, reject or edit the current AI result before moving to another raw message.','info');return;}if(!r.items.length)return;
  let target=r.awaitingAdvance&&delta>0?r.position:r.position+delta;
  if(target>=r.items.length&&r.hasMore){
    r.offset+=r.pageSize;r.position=0;r.selectedId=null;r.awaitingAdvance=false;
    await renderReview();return;
  }
  if(target<0&&r.offset>0){
    r.offset=Math.max(0,r.offset-r.pageSize);r.position=r.pageSize-1;r.selectedId=null;r.awaitingAdvance=false;
    await renderReview();
    if(r.items.length){r.position=r.items.length-1;r.selectedId=r.items[r.position].id;await renderReview();}
    return;
  }
  if(target<0||target>=r.items.length){toast(target<0?'Already at the start of this review queue.':'End of the current review sequence.','info');return;}
  r.awaitingAdvance=false;r.position=target;r.selectedId=r.items[target].id;await renderReview();
}
async function undoReviewLast(){const r=state.review;if(!r.undoToken){toast('There is no review decision available to undo.','info');return false;}try{const d=await api(`/api/workflows/${workflowId()}/quality/undo`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({undo_token:r.undoToken})});r.undoToken=null;r.awaitingAdvance=false;r.selectedId=null;logReviewCommand('undo',`${d.restored} previous decision(s) restored.`);await renderReview();await refreshWorkflow();return true;}catch(e){toast(e.message,'error');return false}}
async function saveReviewSettings(patch){const current=state.review.settings||state.config.review_settings||{};if(patch.mode==='guided')state.review.selected.clear();const body={enabled:patch.enabled??state.review.enabled,mode:patch.mode||current.mode||'guided',processing_path:patch.processing_path||state.review.path||current.processing_path||'processed',auto_advance:patch.auto_advance??current.auto_advance??true,confirm_bulk:patch.confirm_bulk??current.confirm_bulk??true,page_size:patch.page_size??current.page_size??100,sort:patch.sort??state.review.sort??current.sort??'newest'};try{const d=await api(`/api/workflows/${workflowId()}/review/settings`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});state.config.review_mode=d.review_mode;state.config.review_settings=d.review_settings;state.review.mode=d.review_settings.mode;state.review.settings=d.review_settings;await refreshWorkflow();await renderReview();toast('Review settings saved. Existing pending items are unchanged.');}catch(e){toast(e.message,'error');await renderReview()}}
function bindReviewKeyboard(){if(state.view!=='review')return;document.onkeydown=async e=>{if(state.view!=='review'||e.altKey||e.ctrlKey||e.metaKey)return;const tag=document.activeElement?.tagName?.toLowerCase();if(['input','textarea','select'].includes(tag)||document.activeElement?.isContentEditable)return;if(e.key==='j'||e.key==='ArrowDown'){e.preventDefault();moveReviewSelection(1)}else if(e.key==='k'||e.key==='ArrowUp'){e.preventDefault();moveReviewSelection(-1)}else if(e.key==='a'){e.preventDefault();if(state.review.selectedId)executeReviewAction([state.review.selectedId],'approve')}else if(e.key==='r'){e.preventDefault();if(state.review.selectedId)executeReviewAction([state.review.selectedId],'reject')}else if(e.key==='e'){e.preventDefault();const x=state.review.items.find(x=>x.id===state.review.selectedId);if(x)openRecordEditor(x)}else if(e.key==='?'){e.preventDefault();showReviewCommandHelp()}else if(/^[1-9]$/.test(e.key)){const i=Number(e.key)-1;if(state.review.items[i]){e.preventDefault();state.review.selectedId=state.review.items[i].id;state.review.position=i;state.review.awaitingAdvance=false;renderReview()}}};}
function openRecordEditor(record){if(!record)return;const fields=state.config.fields;const html=fields.map(f=>`<div class="field"><label>${esc(f.label)} <small class="muted">${esc(f.type)}</small></label><input class="input edit-val" data-key="${esc(f.name)}" value="${esc(record.data[f.name]===null?'':typeof record.data[f.name]==='object'?JSON.stringify(record.data[f.name]):record.data[f.name])}" placeholder="Empty / null"></div>`).join('');showModal(`<div class="modal-head"><div><div class="eyebrow">RECORD CORRECTION</div><h2>Edit extracted fields</h2></div><button id="closeModal">×</button></div><div class="hint-box" style="margin-bottom:13px">Your changes are saved in a correction log. You can promote the corrected source/result pair into this workflow's few-shot examples.</div><div class="form-grid">${html}</div><div class="modal-actions"><button class="btn btn-quiet" id="cancelEdit">Cancel</button><button class="btn btn-primary" id="saveRecordEdit">Save corrections</button></div>`);$('#closeModal').onclick=closeModal;$('#cancelEdit').onclick=closeModal;$('#saveRecordEdit').onclick=async()=>{const data={};$$('.edit-val').forEach(el=>{let v=el.value.trim();const f=fields.find(x=>x.name===el.dataset.key);if(v==='')data[el.dataset.key]=null;else if(['integer','number'].includes(f.type)){data[el.dataset.key]=Number(v)}else if(['array','object'].includes(f.type)){try{data[el.dataset.key]=JSON.parse(v)}catch{data[el.dataset.key]=v}}else data[el.dataset.key]=v});try{await api(`/api/records/${record.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({data})});closeModal();toast('Correction saved');if(state.view==='inbox')await renderInbox();else renderReview();await refreshWorkflow()}catch(e){toast(e.message,'error')}}}

async function renderCleanup(){const active=await api(`/api/workflows/${workflowId()}/records?status=all&limit=1500`);const activeClean=active.filter(r=>!['duplicate_removed','rejected'].includes(r.status));$('#view-cleanup').innerHTML=`${pageHead('DATA QUALITY','Duplicate cleanup','Find near-duplicate records by comparing their original full messages. Maximum Recall checks every possible pair; automatic cleanup keeps one copy and verifies the remaining dataset.',`<button class="btn btn-secondary" id="scanDuplicates">Find duplicates</button><button class="btn btn-primary" id="autoClean">Auto-clean & verify</button>`)}<div class="grid two-col"><div class="card"><div class="card-head"><h3>Scan settings</h3><span class="tag green">Text-aware</span></div><div class="form-grid"><div class="field"><label>Similarity threshold</label><select id="dupThreshold" class="input"><option value="98">98% · Very strict</option><option value="95" selected>95% · Recommended</option><option value="92">92% · More matches</option><option value="90">90% · Broad</option></select></div><div class="field"><label>Scan mode</label><select id="dupMode" class="input"><option value="exhaustive">Maximum Recall — every pair</option><option value="fast">Fast — limited candidates</option></select></div><div class="field"><label>Candidate limit (Fast only)</label><input id="dupNeighbors" class="input" type="number" min="5" max="500" value="100"></div><div class="field"><label class="toggle-row"><input id="crossDate" type="checkbox" checked> Compare across dates</label><small class="help">Find the same content posted on different days.</small></div></div><div class="hint-box" style="margin-top:14px"><b>Important:</b> Matching uses the full original message, not extracted price or location fields. The original messages are preserved.</div><div class="divider"></div><div class="grid three-col"><div><small class="muted">Loaded records</small><h2>${activeClean.length}</h2></div><div><small class="muted">Already removed</small><h2>${active.length-activeClean.length}</h2></div><div><small class="muted">Scan threshold</small><h2 id="thresholdLabel">95%</h2></div></div></div><div class="card"><div class="card-head"><h3>Duplicate review guide</h3></div><div class="step-list"><div class="step"><div class="step-num">1</div><div><b>Find duplicates</b><small>Review the detected groups. Similarity below 100% means messages differ—check price, area, dates and other changes.</small></div></div><div class="step"><div class="step-num">2</div><div><b>Choose which copy to keep</b><small>For same-date matches, keep your preferred copy. For different dates, auto-clean retains the newest dated copy.</small></div></div><div class="step"><div class="step-num">3</div><div><b>Rescan remaining records</b><small>After every manual decision, Agent Shadi scans again to reveal hidden or transitive duplicates.</small></div></div><div class="step"><div class="step-num">4</div><div><b>Verify zero remaining groups</b><small>Automatic cleaning is not complete until the final verification finds no duplicate groups.</small></div></div></div></div></div><div id="cleanupWork" style="margin-top:15px"></div>`;
  $('#dupThreshold').onchange=()=>$('#thresholdLabel').textContent=$('#dupThreshold').value+'%';$('#scanDuplicates').onclick=scanDuplicates;$('#autoClean').onclick=autoClean;}
async function scanDuplicates(){try{const d=await api(`/api/workflows/${workflowId()}/cleanup/scan`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({threshold:Number($('#dupThreshold').value),scan_mode:$('#dupMode').value,cross_date:$('#crossDate').checked,neighbors:Number($('#dupNeighbors').value)})});state.cleanupId=d.session_id;state.cleanup=d;localStorage.setItem('structura_cleanup_'+workflowId(),state.cleanupId);showCleanupGroup(d);toast(d.complete?'No duplicates found':'Duplicate scan completed')}catch(e){toast(e.message,'error')}}
function diffText(a,b){const at=a.split(/(\s+)/),bt=b.split(/(\s+)/);let common=0;const aa=[],bb=[];for(let i=0;i<Math.max(at.length,bt.length);i++){if(at[i]===bt[i]&&at[i]!==undefined){aa.push(esc(at[i]));bb.push(esc(bt[i]));continue}const x=at[i]||'',y=bt[i]||'';if(x)aa.push(`<span class="diff-del">${esc(x)}</span>`);if(y)bb.push(`<span class="diff-add">${esc(y)}</span>`)}return [aa.join(''),bb.join('')]}
function showCleanupGroup(d){
  state.cleanup=d;const box=$('#cleanupWork');if(!box)return;
  if(d.complete||!d.group){box.innerHTML=`<div class="success-box">No unresolved duplicate groups in this scan. Final verification is complete for this review session.</div>`;return}
  const members=d.group.members;const options=members.map((m,i)=>`<option value="${m.id}" data-row="${m.row_index}">${i+1}. ${esc((Object.values(m.data).filter(Boolean).slice(0,2).join(' · ')||m.posted_at||'Record'))} · ${esc(m.posted_at||'No date')} · ${Number(m.similarity||0).toFixed(2)}%</option>`).join('');
  const left=members[0],right=members[1];
  box.innerHTML=`<div class="card"><div class="card-head"><div><div class="eyebrow">DUPLICATE GROUP ${d.group_index+1} OF ${d.group_count}</div><h3>${members.length} connected similar records</h3><small class="muted">Compare two versions. Each decision removes only the selected duplicate, then rescans the entire remaining dataset—important when a group contains 3 or more messages.</small></div><span class="tag amber">${Math.max(...members.map(x=>x.similarity||0)).toFixed(2)}% max similarity</span></div><div class="form-grid"><div class="field"><label>Version A</label><select id="leftRecord" class="input">${options}</select></div><div class="field"><label>Version B</label><select id="rightRecord" class="input">${options.replace(`value="${left.id}"`,`value="${left.id}" disabled`)}</select></div></div><div id="pairDiff" class="grid two-col" style="margin-top:14px"><div><div class="card-head"><b>Version A · ${esc(left.posted_at||'No date')}</b></div><div class="diff-pane">${esc(left.raw_text)}</div></div><div><div class="card-head"><b>Version B · ${esc(right.posted_at||'No date')}</b></div><div class="diff-pane">${esc(right.raw_text)}</div></div></div><div class="page-actions" style="margin-top:14px"><button id="skipGroup" class="btn btn-secondary">Skip for now</button><button id="keepLeft" class="btn btn-primary">Keep A · remove B · rescan</button><button id="keepRight" class="btn btn-primary">Keep B · remove A · rescan</button></div></div>`;
  const loadPair=async()=>{const a=$('#leftRecord'),b=$('#rightRecord');if(a.value===b.value){const next=members.find(m=>m.id!==a.value);if(next)b.value=next.id;}const la=members.find(m=>m.id===$('#leftRecord').value),rb=members.find(m=>m.id===$('#rightRecord').value);if(!la||!rb||la.id===rb.id)return;try{const result=await api(`/api/cleanup/${state.cleanupId}/compare?left_index=${la.row_index}&right_index=${rb.row_index}`);$('#pairDiff').innerHTML=`<div><div class="card-head"><b>Version A · ${esc(la.posted_at||'No date')}</b><span class="tag">${result.score.toFixed(2)}%</span></div><div class="diff-pane">${result.left_html}</div></div><div><div class="card-head"><b>Version B · ${esc(rb.posted_at||'No date')}</b><span class="tag">${result.warning}</span></div><div class="diff-pane">${result.right_html}</div></div>`;$('#keepLeft').textContent='Keep A · remove B · rescan';$('#keepRight').textContent='Keep B · remove A · rescan'}catch(e){toast(e.message,'error')}};
  $('#leftRecord').onchange=loadPair;$('#rightRecord').onchange=loadPair;loadPair();
  const decide=async(keep,remove)=>{try{const r=await api(`/api/cleanup/${state.cleanupId}/decision`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({keep_record_id:keep,remove_record_id:remove})});showCleanupGroup(r);toast('One duplicate removed; remaining dataset rescanned')}catch(e){toast(e.message,'error')}};
  $('#keepLeft').onclick=()=>decide($('#leftRecord').value,$('#rightRecord').value);$('#keepRight').onclick=()=>decide($('#rightRecord').value,$('#leftRecord').value);
  $('#skipGroup').onclick=async()=>{try{const r=await api(`/api/cleanup/${state.cleanupId}/skip`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({group_index:d.group_index})});showCleanupGroup(r)}catch(e){toast(e.message,'error')}};
}
async function autoClean(){if(!confirm('Automatically remove duplicates? For different dates the newest dated copy is retained. A final verification scan will run.'))return;try{const scan=await api(`/api/workflows/${workflowId()}/cleanup/scan`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({threshold:Number($('#dupThreshold').value),scan_mode:$('#dupMode').value,cross_date:$('#crossDate').checked,neighbors:Number($('#dupNeighbors').value)})});state.cleanupId=scan.session_id;const d=await api(`/api/cleanup/${scan.session_id}/auto`,{method:'POST'});$('#cleanupWork').innerHTML=`<div class="success-box"><b>Automatic cleanup finished and verified.</b><br>${d.audit.original_rows} original records · ${d.audit.removed_count} duplicates removed · ${d.audit.initial_groups} initial groups · ${d.audit.passes} passes · ${d.audit.final_groups} final groups.</div><pre class="code-box" style="margin-top:12px">${esc(pretty(d.audit.decisions.slice(0,80)))}</pre>`;toast(`${d.audit.removed_count} duplicate records removed`);await refreshWorkflow()}catch(e){toast(e.message,'error')}}

async function renderExport(){const d=await api(`/api/workflows/${workflowId()}/dashboard`);$('#view-export').innerHTML=`${pageHead('OUTPUTS','Export your dataset','Download the records that have been approved, or include all statuses for auditing and further processing.',``)}<div class="grid two-col"><div class="card"><div class="card-head"><h3>Export settings</h3></div><div class="field"><label>Record status</label><select id="exportStatus" class="input"><option value="approved">Approved only (recommended)</option><option value="all">All records, including review and rejected</option><option value="needs_review">Waiting for review</option></select></div><div class="divider"></div><div class="grid three-col"><button class="btn btn-secondary" id="exportXlsx">⇩ Excel .xlsx</button><button class="btn btn-secondary" id="exportCsv">⇩ CSV</button><button class="btn btn-secondary" id="exportJson">⇩ JSON</button></div><div class="hint-box" style="margin-top:14px">Exports include your configured fields, original full message, source date, confidence, per-field provenance, warnings and validation errors.</div></div><div class="card"><div class="card-head"><h3>Dataset summary</h3><span class="tag green">Local database</span></div><div class="step-list"><div class="step"><div class="step-num">1</div><div><b>${d.stats.records} records extracted</b><small>All stored structured outputs</small></div></div><div class="step"><div class="step-num">2</div><div><b>${d.stats.approved} approved records</b><small>Recommended export selection</small></div></div><div class="step"><div class="step-num">3</div><div><b>${d.stats.needs_review} waiting for review</b><small>Review before relying on uncertain fields</small></div></div><div class="step"><div class="step-num">4</div><div><b>${d.stats.duplicate_removed} duplicates removed</b><small>Excluded from normal export unless status=all</small></div></div></div></div></div>`;$('#exportXlsx').onclick=()=>downloadExport('xlsx');$('#exportCsv').onclick=()=>downloadExport('csv');$('#exportJson').onclick=()=>downloadExport('json')}
function downloadExport(format){const status=$('#exportStatus').value;window.location=`/api/workflows/${workflowId()}/export?format=${format}&status=${status}`}

async function renderLearning(){const rows=await api(`/api/workflows/${workflowId()}/corrections`);state.corrections=rows;$('#view-learning').innerHTML=`${pageHead('CONTINUOUS IMPROVEMENT','Corrections library','Every manual edit is stored with the original model output and your corrected result. Promote reliable corrections into examples to help the model handle similar inputs.',`<button class="btn btn-secondary" data-nav="builder">Edit prompt & examples</button>`)}<div class="card"><div class="card-head"><h3>Saved corrections <span class="tag violet">${rows.length}</span></h3></div>${rows.length?rows.map(r=>`<div class="record-card"><div class="record-top"><div><div class="message-meta"><span>${esc(r.created_at.slice(0,16))}</span><span>${Object.keys(JSON.parse(r.changed_json||'{}')).length} fields changed</span></div><b style="font-size:12px">Correction ${esc(r.id.slice(0,8))}</b></div><button class="btn btn-primary btn-sm promote-correction" data-id="${r.id}">＋ Promote as LLM example</button></div><div class="grid two-col" style="margin-top:9px"><div><small class="muted">Original result</small><pre class="code-box">${esc(r.original_json)}</pre></div><div><small class="muted">Corrected result</small><pre class="code-box">${esc(r.corrected_json)}</pre></div></div><details style="margin-top:8px"><summary class="muted">Source message</summary><div class="diff-pane" style="margin-top:7px">${esc(r.raw_text)}</div></details></div>`).join(''):empty('No corrections saved yet','Edit a record in the Review section. Your changes will appear here.','✳')}</div>`;$$('.promote-correction').forEach(b=>b.onclick=async()=>{try{const d=await api(`/api/corrections/${b.dataset.id}/promote`,{method:'POST'});toast(`Correction promoted. Workflow now has ${d.examples} examples.`)}catch(e){toast(e.message,'error')}})}

async function renderSettings(){const m=await api('/api/settings/model');state.model=m;$('#view-settings').innerHTML=`${pageHead('MODEL & APPLICATION SETTINGS','Connect your LLM','Agent Shadi uses an OpenAI-compatible API. This works with local runtimes such as LM Studio and Ollama-compatible servers, or a hosted model provider.',``)}<div class="grid two-col"><div class="card"><div class="card-head"><h3>Model connection</h3><span class="tag violet">OpenAI-compatible</span></div><div class="field"><label>API base URL</label><input id="modelBase" class="input" value="${esc(m.base_url||'http://127.0.0.1:1234/v1')}" placeholder="http://127.0.0.1:1234/v1"><small class="help">Use the base endpoint ending in /v1, not /chat/completions.</small></div><div class="field" style="margin-top:12px"><label>Loaded model</label><select id="modelPicker" class="input"><option value="">Discovering models…</option></select><div id="modelManualWrap" style="display:none;margin-top:8px"><input id="modelName" class="input" value="${esc(m.model||'')}" placeholder="Paste the exact model ID returned by your server"></div><small class="help">Choose a readable model name from the server list. Agent Shadi stores the exact API ID automatically; the long filesystem path stays out of the way.</small></div><div class="field" style="margin-top:12px"><label>API key (optional for local models)</label><input id="modelKey" class="input" type="password" placeholder="${m.api_key_set?'Saved key — leave blank to keep it':'Paste API key if required'}" autocomplete="new-password"></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Model input</label><select id="modelInputMode" class="input"><option value="raw" ${m.input_mode==='raw'?'selected':''}>Original raw message (recommended)</option><option value="preprocessed" ${m.input_mode==='preprocessed'?'selected':''}>Preprocessed copy</option></select></div><div class="field"><label>Timeout (seconds)</label><input id="modelTimeout" class="input" type="number" min="10" max="900" value="${m.timeout||150}"></div></div><label class="toggle-row" style="margin-top:13px"><input id="modelEnabled" type="checkbox" ${m.enabled?'checked':''}> Enable LLM extraction</label><div class="hint-box" style="margin-top:8px">When enabled, Agent Shadi checks the live endpoint and confirms the selected model is listed before extraction. Saving connection details triggers a fresh check.</div><label class="toggle-row" style="margin-top:12px"><input id="allowRulesOnly" type="checkbox" ${m.allow_rules_only?'checked':''}> Allow rules-only extraction without an LLM</label><small class="help">Optional fallback. This only applies deterministic rules and explicit label/value matching; it does not understand arbitrary free-form messages. Leave off unless you intentionally want this limited mode.</small><div class="model-live-card" id="modelConnectionSummary" style="margin-top:12px"><div class="model-live-row"><b>Live connection status</b><span class="tag amber">Checking…</span></div><p>Checking whether the configured model server is actually responding.</p></div><div class="page-actions" style="margin-top:16px"><button class="btn btn-secondary" id="saveModel">Save model settings</button><button class="btn btn-quiet" id="refreshModelStatus">Refresh status</button><button class="btn btn-primary" id="testModel">Test connection</button></div><div id="modelTestResult" style="margin-top:13px"></div></div>
<div class="card"><div class="card-head"><h3>How it works</h3></div><div class="step-list"><div class="step"><div class="step-num">01</div><div><b>Local LLM</b><small>LM Studio example: start the local server, load a model, then use <code>http://127.0.0.1:1234/v1</code>.</small></div></div><div class="step"><div class="step-num">02</div><div><b>Other local runtimes</b><small>Ollama or another server may expose an OpenAI-compatible endpoint. Use the exact URL and model identifier it provides.</small></div></div><div class="step"><div class="step-num">03</div><div><b>Hosted providers</b><small>Enter the provider's compatible API base URL, model name and API key. Your source messages are sent to that provider.</small></div></div><div class="step"><div class="step-num">04</div><div><b>Live connection checks</b><small>Agent Shadi checks the endpoint automatically. Use Test connection for an immediate diagnostic, then test your workflow prompt with one real message.</small></div></div></div><div class="warning-box" style="margin-top:14px">API keys are stored in the local application database with owner-only file permissions. They are not encrypted by this preview build. Do not expose this local server to a public network.</div></div></div><div class="card" style="margin-top:15px"><div class="card-head"><h3>Workflow privacy & storage</h3><span class="tag green">Local-first</span></div><p class="muted">Projects, raw messages, extracted records, correction logs, channel configuration and browser sessions are stored under the application's private <code>data/</code> directory. Nothing is uploaded unless you configure a hosted LLM endpoint or use Telegram/Rubika collection.</p></div>`;
  populateModelPicker(m.available_models||[],m.model||'');$('#modelPicker').onchange=()=>{const value=$('#modelPicker').value;if(value==='__manual_model__'){$('#modelManualWrap').style.display='block';$('#modelName').focus();}else{if(value)$('#modelName').value=value;$('#modelManualWrap').style.display='none';if(state.model)state.model.model=value;}};$('#modelName').oninput=()=>{if(state.model)state.model.model=$('#modelName').value;};$('#saveModel').onclick=saveModel;$('#refreshModelStatus').onclick=()=>checkModelStatus({force:true});$('#testModel').onclick=async()=>{try{await saveModel({notify:false,refresh:false});$('#modelTestResult').innerHTML='<div class="muted">Testing live endpoint and selected model…</div>';const d=await api('/api/settings/model/test',{method:'POST'});$('#modelTestResult').innerHTML=`<div class="success-box">${esc(d.message)}<br>${(d.models||[]).map(name=>esc(modelShortLabel(name))).join(', ')||'Endpoint returned no model list.'}</div>`;state.model=await api('/api/settings/model');await checkModelStatus({force:true});}catch(e){$('#modelTestResult').innerHTML=`<div class="warning-box">${esc(e.message)}</div>`;await checkModelStatus({force:true});}};await checkModelStatus({force:true});}
async function saveModel({notify=true,refresh=true}={}){const payload={enabled:$('#modelEnabled').checked,allow_rules_only:$('#allowRulesOnly').checked,base_url:$('#modelBase').value,model:$('#modelName').value,api_key:$('#modelKey').value,input_mode:$('#modelInputMode').value,temperature:0,timeout:Number($('#modelTimeout').value)};const d=await api('/api/settings/model',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});state.model=d;state.modelHealth={status:'checking',message:'Settings saved. Checking the new endpoint…'};updateModelStatus();renderModelConnectionSummary();if(notify)toast('Model settings saved locally');if(refresh)await checkModelStatus({force:true});return d}

function showModal(html){$('#modal').style.width='min(680px,100%)';$('#modal').innerHTML=html;$('#modalBackdrop').classList.add('show')}
function closeModal(){$('#modalBackdrop').classList.remove('show')}
async function newWorkflow(){showModal(`<div class="modal-head"><div><div class="eyebrow">NEW WORKFLOW</div><h2>Create a data workflow</h2></div><button id="closeModal">×</button></div><div class="field"><label>Workflow name</label><input id="newWfName" class="input" placeholder="e.g. Customer feedback analysis"></div><div class="field" style="margin-top:12px"><label>Start from a template</label><select id="newWfTemplate" class="input"><option value="custom">Custom dataset — start flexible</option><option value="real_estate_fa">Property listings — advanced price & area guardrails</option><option value="jobs">Job listings</option><option value="vehicles">Vehicle classifieds</option></select></div><div class="modal-actions"><button class="btn btn-quiet" id="cancelNew">Cancel</button><button class="btn btn-primary" id="createNew">Create workflow</button></div>`);$('#closeModal').onclick=closeModal;$('#cancelNew').onclick=closeModal;$('#createNew').onclick=async()=>{try{const name=$('#newWfName').value.trim();if(!name)throw new Error('Enter a workflow name');const w=await api('/api/workflows',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,template:$('#newWfTemplate').value})});state.workflowId=w.id;closeModal();await refreshBootstrap();toast('New workflow created');setView('builder')}catch(e){toast(e.message,'error')}}}

// Command palette and keyboard-first navigation.
const commandViews=[
  ['overview','Dashboard','⌂','Workspace overview'],['builder','Workflow Builder','⌘','Schema, prompt and extraction rules'],
  ['sources','Sources & Collection','◎','Connect Telegram, Rubika, web and files'],['inbox','Dataset Explorer','▤','Inspect source messages and extracted records'],
  ['review','Review Studio','◉','One-by-one approval, batch review and standalone Review Desk'],['cleanup','Quality & Duplicates','⌁','Find near-duplicates and data issues'],
  ['export','Exports & Share','⇧','Download structured data'],['agent','Ask Agent Shadi','✳','Get LLM-powered workflow assistance'],['settings','Model & Settings','⚙','Configure your LLM connection']
];
function openCommandPalette(query=''){
  showModal(`<div class="modal-head"><div><div class="eyebrow">COMMAND PALETTE · CTRL / CMD + K</div><h2>Where should we go?</h2></div><button id="closeCommand">×</button></div><input id="commandSearch" class="input" placeholder="Search pages and actions…" value="${esc(query)}" autofocus><div class="command-list" id="commandResults"></div><div class="agent-privacy-note">Use the keyboard to navigate your workspace. Search does not send anything to the model.</div>`);
  const render=()=>{const q=$('#commandSearch').value.trim().toLowerCase();const rows=commandViews.filter(x=>!q||`${x[1]} ${x[3]}`.toLowerCase().includes(q));$('#commandResults').innerHTML=rows.map(x=>`<button class="command-item" data-nav="${x[0]}"><span>${x[2]}</span><b>${x[1]}</b><small>${x[3]}</small></button>`).join('')||'<div class="empty">No matching workspace command.</div>';};
  $('#commandSearch').oninput=render;$('#closeCommand').onclick=closeModal;render();setTimeout(()=>$('#commandSearch')?.focus(),30);
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-nav], [data-view]');if(!b)return;const view=b.dataset.nav||b.dataset.view;if(view){e.preventDefault();if(b.classList.contains('command-item'))closeModal();setView(view)}},true);
$('#workflowSelect').addEventListener('change',async e=>{state.workflowId=e.target.value;await loadWorkflow();setView('overview')});
$('#newWorkflowBtn').onclick=newWorkflow;$('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()};
$('#globalSearch')?.addEventListener('focus',()=>openCommandPalette($('#globalSearch').value));
$('#globalSearch')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();openCommandPalette(e.target.value)}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommandPalette()}if(e.key==='Escape')closeModal()});
$('#openDiagnostics')?.addEventListener('click',openDiagnostics);
document.body.classList.add('dashboard-view-active');
$('#themeToggle')?.addEventListener('click',()=>{document.body.classList.toggle('shadi-light');const theme=document.body.classList.contains('shadi-light')?'light':'dark';try{localStorage.setItem('agentShadiTheme',theme)}catch{}toast(theme==='light'?'Light appearance enabled':'Dark appearance enabled')});
try{if(localStorage.getItem('agentShadiTheme')==='light')document.body.classList.add('shadi-light')}catch{}
startModelStatusMonitor();
(async()=>{try{await refreshBootstrap();setView('overview')}catch(e){$('#content').innerHTML=`<div class="warning-box">Application could not initialize: ${esc(e.message)}. Check the server terminal for details.</div>`}})();
